-- Layercake.fn_silv_daily_count_detail_as_known_at (src/sql/Layercake/Functions/Layercake.fn_silv_daily_count_detail_as_known_at.sql) (changed)
/*====================================================================
    Layercake.fn_silv_daily_count_detail_as_known_at
    Daily counts at the silv_daily_count_detail grain as they stood at
    @as_known_at (REQ-020, ADR-008, RULE-119 to RULE-121): the stored
    figure (0 where the cell has no stored row) minus the cell's changes
    in silv_daily_count_adjustment written strictly after @as_known_at.
    A change written exactly at @as_known_at is part of the figure
    (Q-049, server local time). A date first loaded after @as_known_at
    gives its first-load figures (Q-050). A cell with no stored row is
    returned only when one of its figures is not 0 at @as_known_at.
    Any NULL parameter returns no rows.
    MOD-028 (REQ-026, RULE-155): the cell includes payment_method_id,
    payer_type_id and concession_type_id. Adjustment rows written before
    deployment, and by the restating run, carry -2, so for a time before
    deployment the figures are exact summed over the three columns but
    not split by segment (RULE-163).
    MOD-031 (REQ-027, RULE-176, RULE-179): the cell also includes
    local_group_id, contact_country_id and contact_region. Rows written
    before that deployment carry their own country and region in the
    contact columns and -2 in local_group_id, so for a time before it the
    figures are exact by own country and wherever region, country_id and
    local_group_id are summed over, but not split by the local group's
    region or country.
====================================================================*/
CREATE OR ALTER FUNCTION Layercake.fn_silv_daily_count_detail_as_known_at
(
    @date_from   date,
    @date_to     date,
    @as_known_at datetime2(3)
)
RETURNS TABLE
AS
RETURN
    SELECT
        f.[date],
        f.region,
        f.country_id,
        f.gender_id,
        f.grade,
        f.membership_status_id,
        f.payment_method_id,
        f.payer_type_id,
        f.concession_type_id,
        f.local_group_id,
        f.contact_country_id,
        f.contact_region,
        ISNULL(SUM(f.active_count), 0)            AS active_count,
        ISNULL(SUM(f.paid_count), 0)              AS paid_count,
        ISNULL(SUM(f.paid_count_event), 0)        AS paid_count_event,
        ISNULL(SUM(f.event_join_count), 0)        AS event_join_count,
        ISNULL(SUM(f.event_renewal_count), 0)     AS event_renewal_count,
        ISNULL(SUM(f.event_readmission_count), 0) AS event_readmission_count,
        ISNULL(SUM(f.event_lapse_count), 0)       AS event_lapse_count
    FROM (
        SELECT
            d.[date], d.region, d.country_id, d.gender_id, d.grade, d.membership_status_id,
            d.payment_method_id, d.payer_type_id, d.concession_type_id,
            d.local_group_id, d.contact_country_id, d.contact_region,
            d.active_count, d.paid_count, d.paid_count_event, d.event_join_count,
            d.event_renewal_count, d.event_readmission_count, d.event_lapse_count,
            1 AS is_stored
        FROM Layercake.silv_daily_count_detail AS d
        WHERE d.[date] BETWEEN @date_from AND @date_to
          AND @as_known_at IS NOT NULL

        UNION ALL

        -- Undo every change written after T.
        SELECT
            a.[date], a.region, a.country_id, a.gender_id, a.grade, a.membership_status_id,
            a.payment_method_id, a.payer_type_id, a.concession_type_id,
            a.local_group_id, a.contact_country_id, a.contact_region,
            -a.active_count_change, -a.paid_count_change, -a.paid_count_event_change, -a.event_join_count_change,
            -a.event_renewal_count_change, -a.event_readmission_count_change, -a.event_lapse_count_change,
            0 AS is_stored
        FROM Layercake.silv_daily_count_adjustment AS a
        WHERE a.[date] BETWEEN @date_from AND @date_to
          AND a.written_at > @as_known_at
    ) AS f
    GROUP BY f.[date], f.region, f.country_id, f.gender_id, f.grade, f.membership_status_id,
             f.payment_method_id, f.payer_type_id, f.concession_type_id,
             f.local_group_id, f.contact_country_id, f.contact_region
    -- A stored row is always returned, even all zeros; a cell that exists only in the history
    -- (removed after T) is returned only if it had a figure at T.
    HAVING MAX(f.is_stored) = 1
        OR SUM(f.active_count) <> 0
        OR SUM(f.paid_count) <> 0
        OR SUM(f.paid_count_event) <> 0
        OR SUM(f.event_join_count) <> 0
        OR SUM(f.event_renewal_count) <> 0
        OR SUM(f.event_readmission_count) <> 0
        OR SUM(f.event_lapse_count) <> 0;
GO
-- Layercake.vw_silv_daily_count_adjustment_review (src/sql/Layercake/Views/Layercake.vw_silv_daily_count_adjustment_review.sql) (changed)
/*====================================================================
    Layercake.vw_silv_daily_count_adjustment_review
    The daily count adjustments for review (RULE-122, Q-051): one row per
    silv_daily_count_adjustment row and measure whose change is not 0,
    keeping the cell's grain columns. Not summed to date level, so
    changes that cancel out across cells stay visible. measure_name is
    the silv_daily_count_detail column name.
    MOD-028 (RULE-155): the cell's segment ids, copied from the
    adjustment row; rows written before deployment show -2 (RULE-162).
    MOD-031 (RULE-176): the cell's local group, own country and its
    region, copied from the adjustment row, so a move between local
    groups shows as -1 and +1 on two rows; rows written before that
    deployment show -2 in local_group_id (RULE-179).
====================================================================*/
CREATE OR ALTER VIEW Layercake.vw_silv_daily_count_adjustment_review
AS
SELECT
    a.adjustment_id,
    a.run_id,
    a.written_at,
    a.[date],
    a.region,
    a.country_id,
    a.gender_id,
    a.grade,
    a.membership_status_id,
    a.payment_method_id,
    a.payer_type_id,
    a.concession_type_id,
    a.local_group_id,
    a.contact_country_id,
    a.contact_region,
    -- ISNULL only makes the column NOT NULL, as designed: a VALUES column is always reported nullable.
    ISNULL(m.measure_name, '') AS measure_name,
    m.change_value
FROM Layercake.silv_daily_count_adjustment AS a
CROSS APPLY (
    VALUES (CAST('active_count' AS varchar(30)), a.active_count_change),
           ('paid_count', a.paid_count_change),
           ('paid_count_event', a.paid_count_event_change),
           ('event_join_count', a.event_join_count_change),
           ('event_renewal_count', a.event_renewal_count_change),
           ('event_readmission_count', a.event_readmission_count_change),
           ('event_lapse_count', a.event_lapse_count_change)
) AS m (measure_name, change_value)
WHERE m.change_value <> 0;
GO
-- Layercake.usp_load_silv_member_base (src/sql/Layercake/Procedures/Layercake.usp_load_silv_member_base.sql) (changed)
/*====================================================================
    Layercake.usp_load_silv_member_base
    Silver layer - loads one table
====================================================================*/

/*====================================================================
    8. Layercake.silv_member_base   (was #mbase)
    ------------------------------------------------------------------
    The per-contact base every downstream silver derivation reads.
    Full re-derive: truncate + insert in one transaction, so a failure
    leaves the previous run's content intact.

    #rics_record feeds it and is used nowhere else, so it stays as a
    #temp table inside this module. #enr_base is staged from
    Layercake.vw_enrolment_base, which holds the qualifying-row rules
    themselves - module 10 reads the same view so the anomaly report
    cannot drift from the driver.

    v6 SOURCING: dates come from a per-contact aggregate of #enr_base.
      enrolment_date: earliest clamped enrolment date across ALL staged
          rows - Part-1 rows AND enrolment dates riding on Part-2
          election rows, EXCEPT RPQ rows, which supply none (a direct
          entry never enrolled - the rule and the reason are in the
          view). So a contact whose only enrolment date sat on an RPQ
          election row lands here with enrolment_date null, and module 9
          derives the Join/RPQ it should always have had.
      election_date:  earliest election date across Part-2 rows.
      is_rpq:         from the row that supplied the earliest election
          date (an RPQ-flagged row wins a date tie).
    ENROLMENT EXCEPTIONS (07): where the aggregate finds nothing, the
    curated ref_enrolment_exception dates are coalesced in - real rows
    always win, the fallback self-retires. Since 20260928_02 that table
    is maintained by the pipeline (module 8a,
    usp_load_ref_enrolment_exception, runs immediately before this one)
    rather than captured once by a phase 03 seed, which is what stopped
    a daily load and a from-scratch rebuild disagreeing on the most
    recent day's counts. Nothing here changed: the coalesce is per date
    and real rows still win, and superseded_at on the exception row is
    DELIBERATELY NOT TESTED below. A superseded row is already inert
    wherever real data covers it, and it is still filling a real gap
    wherever the real rows supply only one of the two dates - testing
    the flag would reopen that gap.
    ENROLMENT AFTER THE FIRST PAID YEAR (subs-history backdating): the
    recorded enrolment date (real row or 07 fallback) is then compared
    with the contact's FIRST PAID campaign year in silv_payment_events.
    Where the recorded date sits in a LATER campaign year, the source
    says "joined" years after the subs history says they were paying,
    and derived as recorded the Join landed in a year they had not
    paid - counting them as paid from the Join event - with the earlier
    payments falling through as Renewals before any Join. So the
    enrolment date is BACKDATED to the first paid year: the payment
    event's date in that year (renewal_date_adj, else the cash
    transaction date, clamped inside the year; the year start when
    neither is known). The Join then lands where the paying started,
    every later paid year derives as a Renewal, and the recorded year
    gets no Join of its own - the contact counts as paid there only if
    a paid position exists for it. Same campaign year = no change (the
    Join year IS the first paid year already).
    The ELECTION date gets the same treatment ONLY where there is no
    enrolment date at all: the election is then the Join anchor (a
    Join/RPQ, or the Change that opens the state range), and a recorded
    election in a later campaign year than the first paid one produced
    the same "joiner after years of Renewals". Where an enrolment date
    exists the election is never moved - the enrolment is the anchor
    and the grade change stays where the source put it.
    ENROLMENT BEFORE THE FIRST PAID YEAR (subs-history forward-dating):
    the same rule in the other direction. A contact with a valid
    enrolment in CY N but NO paid position for N, whose first paid
    position is a LATER campaign year, got its Join in N - a year they
    had not paid - and the first paid year fell through as a Renewal.
    The first paid year is the join year, so the enrolment date is
    moved FORWARD to it, to the same join date the backdating uses.
    BOUNDED BY THE PAYMENT HISTORY, and the bound is load-bearing:
    silv_payment_events only reaches back as far as the subs history
    that was loaded (CY2022 at the time of writing), so for a member
    who enrolled before that, "first paid year" is just the first year
    of data and says nothing about when they started paying. Unbounded,
    the rule would move every long-standing member's Join into the
    first loaded year. So a date is only moved forward where its
    recorded campaign year is ON OR AFTER the earliest campaign year in
    silv_payment_events (@pay_floor_cy) - only there is "no payment in
    the recorded year" evidence of anything. Backdating needs no bound:
    a payment EARLIER than the recorded date is always evidence.
    The ELECTION date is moved forward in two cases:
      * no enrolment date at all - the election is the Join anchor, so
        it takes the rule exactly as the enrolment date would (the
        mirror of the backdated case above);
      * the enrolment date WAS moved forward and the recorded election
        sits before the new join date - left there, the Change would
        precede the Join, open the state range in the unpaid year the
        rule exists to close, and the later Join would drop the member
        back to Candidate. The election is carried to the join date, so
        the two land on the same day and the day ends elected (module
        11 orders enrolment before election). An election on or after
        the join date is not touched.
    Kept visible, like the 07 exceptions: recorded_enrolment_date /
    recorded_election_date hold the date the source recorded and
    enrolment_from_subs_history / election_from_subs_history mark the
    row, in either direction (recorded > effective = backdated,
    recorded < effective = moved forward); module 10 reports the
    cohorts as ENROLMENT_AFTER_FIRST_PAID / ELECTION_AFTER_FIRST_PAID
    and ENROLMENT_BEFORE_FIRST_PAID / ELECTION_BEFORE_FIRST_PAID.
    Note the lapse invalidation below tests the MOVED date. Backdated:
    a contact lapse between the first paid year and the recorded
    enrolment now stands as a real Lapse rather than being treated as
    stale - the member did lapse, and a later payment re-opens the
    state range as a Readmission. Moved forward: a contact lapse
    BEFORE the new join date is invalidated as stale, like any other
    lapse that predates the Join (STALE_LAPSE_IGNORED in module 10).

    RETIREMENT DATE (MOD-018, ADR-005, RULE-100/101): retirement_date is
    the DERIVED date from Layercake.vw_silv_derived_retirement_date - the
    Renewal Date of the contact's earliest live 'Retired Conc.' Campaign
    Year in brnz_subs_status - not apuk_retirementdate, which is entered
    by hand and is not always trustworthy. Null where the contact has no
    derived date: no fallback to apuk_retirementdate or 'First Retired
    Year' (Q-040). Only the value changes; the row set does not. Events,
    annual rate base and (through silv_member_profile) the daily count
    read this column for Practising / Retired and pick it up unchanged.

    COUNTRY BY LOCAL GROUP (MOD-031, REQ-027, RULE-172, RULE-175):
    country_id, local_group_id and contact_country_id come from
    Layercake.vw_silv_contact_local_group, the one place that decides
    them, joined on the contact's ContactId (one view row per live
    brnz_contact row). country_id is the usable local group's country,
    else the own country; contact_country_id is the own country, derived
    exactly as country_id was before (0 where rics_countryid is null or
    not in silv_ref_country). Only the values change; the row set does not.

    DRIVER EXCLUSIONS:
      * Student grade (200000003) on the latest rics record - 'Rules to
        note' #2 - UNLESS the Student status is SUPERSEDED in the
        enrolment history: the most recently created Student application
        is ended, and a qualifying enrolment/election row was created on
        or after it (Layercake.vw_student_superseded, where the test is
        defined). The grade is stale in that case - the Student row is
        closed and an APC / Associate row opened, typically minutes
        apart on the same day, and the rics record never moved - so the
        contact is kept and treated as any other member-base row.
      * NO RICS RECORD AT ALL - a contact with no row in
        brnz_rics_record has no membership record behind it, so it is
        not a member by the source definition and produces no events.
        The excluded cohort is logged as NO_RICS_RECORD by
        usp_load_silv_data_anomaly (module 10) for feedback to the
        client, and the same test is repeated on the payment-derived
        Readmission in module 9 - that is the only event that can open
        a state range without a silv_member_base row.
      * NO TRANSACTION HISTORY - a contact with no row in
        brnz_cust_trans has never transacted, so it is not a valid
        contact and counts as neither active nor paid. Same treatment
        as the rics-record exclusion: no member base row, no events, no
        state range, and the test repeated on the Readmission in module
        9. The PAID count needs no separate test - it is derived from
        the same state-range join as the active count, so a contact
        with no range is dropped from both.
        Reported as NO_TRANSACTIONS by module 10, but only where the
        contact HAS a valid enrolment or election - a contact with
        neither is not a member on any reading, so removing it is not
        an anomaly worth reporting.
====================================================================*/
create or alter procedure Layercake.usp_load_silv_member_base
    @run_id uniqueidentifier = null
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    declare @log_id     bigint,
            @ins        int,
            @del        int,
            @rc         int,
            @substep_ts datetime2(3),
            @err        nvarchar(4000),
            @pay_floor_cy int,
            @step       nvarchar(128);

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'silver', 'silv_member_base', @log_id output;
        set @substep_ts = sysdatetime();

        -- latest rics record per membership number, excluding test contacts.
        -- The Student grade (apuk_membergrade = 200000003) is NOT pre-filtered
        -- here: the latest record's grade is carried through so the driver
        -- below can exclude Student contacts outright.
        -- This row set is also the driver's DEFINITION OF "has a rics record":
        -- a contact number absent from it has no membership record at all.
        -- statecode = 0 deliberately NOT applied - deactivated records would
        -- otherwise drop lapse dates (open issue with Raj).
        select *
        into #rics_record
        from (
            select
                rec.apuk_ricsmembershipnumber,
                rec.apuk_lapseddate,
                rec.apuk_retirementdate,
                rec.apuk_lapsecode,
                rec.apuk_membergrade,
                row_number() over (partition by rec.apuk_ricsmembershipnumber order by rec.ModifiedOn desc) n
            from Layercake.brnz_rics_record rec
            where rec._is_deleted = 0
              and rec.apuk_ricsmembershipnumber is not null
              and not exists (select 1
                              from Layercake.brnz_contact_test_record tst
                              where tst.contactid = rec.apuk_contactid
                                and tst._is_deleted = 0)
        ) v
        where v.n = 1;
        set @rc = @@rowcount;

        create unique clustered index cx_rics on #rics_record (apuk_ricsmembershipnumber);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #rics_record (latest per member)', @rc, @substep_ts output;

        -- v6: enrolment source rows, staged once into #enr_base so the
        -- per-contact aggregate, the lineage resolver and the RPQ flag all
        -- read the SAME row set.
        --
        -- THE RULES THEMSELVES LIVE IN Layercake.vw_enrolment_base - part 1
        -- (valid enrolments) and part 2 (elections), with every rule and its
        -- history commented there. They moved out of this module so
        -- usp_load_silv_data_anomaly can apply the identical test when it
        -- decides whether an EXCLUDED contact nevertheless had a valid
        -- enrolment or election. It is a view, so the plan is the same as
        -- when the two statements sat here.
        -- Materialised into a #temp because it is read three times below.
        select *
        into #enr_base
        from Layercake.vw_enrolment_base;
        set @rc = @@rowcount;

        create clustered index cx_enr_base on #enr_base ([Contact No]);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #enr_base (enrolment + election rows)', @rc, @substep_ts output;

        -- contacts whose Student status is superseded in the enrolment
        -- history: the latest Student application is ended and a qualifying
        -- row was created on or after it. The rule lives in
        -- Layercake.vw_student_superseded, shared with module 10 and the
        -- reconciliation scripts. Staged so the driver's Student test below
        -- is a seek, and so the cohort size lands in the progress log. The
        -- view is one row per contact; the unique index holds it to that.
        select [Contact No] as contact_no
        into #student_superseded
        from Layercake.vw_student_superseded;
        set @rc = @@rowcount;

        create unique clustered index cx_student_superseded on #student_superseded (contact_no);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #student_superseded (Student grade overridden)', @rc, @substep_ts output;

        -- the contact's FIRST PAID campaign year, and the date a payment event
        -- in it carries in module 9 (renewal_date_adj, else the cash
        -- transaction date) clamped inside that campaign year
        -- (01 Oct Y-1 .. 30 Sep Y), falling back to the year start when
        -- neither date is known. The driver below moves a recorded
        -- enrolment date that sits in a DIFFERENT campaign year to this
        -- date: backdated from a later year, forward-dated from an earlier
        -- one (the forward move bounded by @pay_floor_cy, staged next).
        -- Read from silv_payment_events (module 7, built before this module)
        -- so "paid" stays defined in exactly one place. One row per contact;
        -- the unique index asserts it.
        select v.contact_no,
               v.campaign_year                     as first_paid_cy,
               case when d.d < cy.cy_start then cy.cy_start
                    when d.d > cy.cy_end   then cy.cy_end
                    else d.d end                   as join_date
        into #first_paid
        from (
            select p.contact_no, p.campaign_year, p.renewal_date_adj, p.payment_date,
                   row_number() over (partition by p.contact_no order by p.campaign_year) as rn
            from Layercake.silv_payment_events p
        ) v
        cross apply (select datefromparts(v.campaign_year - 1, 10, 1) as cy_start,
                            datefromparts(v.campaign_year,     9, 30) as cy_end) cy
        cross apply (select cast(coalesce(v.renewal_date_adj, v.payment_date, cy.cy_start) as date) as d) d
        where v.rn = 1;
        set @rc = @@rowcount;

        create unique clustered index cx_first_paid on #first_paid (contact_no);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #first_paid (first paid campaign year per contact)', @rc, @substep_ts output;

        -- the FLOOR of the payment history: the earliest campaign year
        -- silv_payment_events holds for anyone. A recorded date is only
        -- moved FORWARD to the first paid year where its own campaign year
        -- is on or after this - before it there is no subs history to be
        -- missing from, so "first paid later" is the edge of the data, not a
        -- fact about the member (see the header). Derived, not configured,
        -- so loading earlier subs history widens the rule by itself; the
        -- value goes into the progress log because a stray early payment row
        -- would widen it too, and that should be visible. Null on an empty
        -- payment table: every comparison below is then false, nothing moves.
        select @pay_floor_cy = min(first_paid_cy) from #first_paid;
        set @step = concat(N'payment history floor: CY', isnull(cast(@pay_floor_cy as nvarchar(10)), N' (none)'),
                           N' (forward-dating bound)');
        exec Layercake.usp_etl_log_progress @log_id, @step, null, @substep_ts output;

        begin tran;

        -- full re-derive: the previous content is replaced wholesale inside
        -- this transaction, so a failure leaves the last good version in place
        select @del = count(*) from Layercake.silv_member_base;
        truncate table Layercake.silv_member_base;

        insert into Layercake.silv_member_base
        (contact_id, contact_no, enrolment_date, election_date, is_rpq, election_enr_id,
         enrolment_from_exception, election_from_exception,
         recorded_enrolment_date, enrolment_from_subs_history,
         recorded_election_date, election_from_subs_history,
         contact_lapsed_date, lapsed_date,
         lapse_reason_id, lapse_reason_name, retirement_date, source_enr_id, rpq_variant_id,
         country_id, gender_id, local_group_id, contact_country_id)
        select
            c.ContactId                             as contact_id,
            c.Rics_contactno                        as contact_no,
            dts.enrolment_date                      as enrolment_date,
            dts.election_date                       as election_date,
            isnull(cast(elec.is_rpq as int), 0)     as is_rpq,
            elec.[ENR ID]                           as election_enr_id,
            iif(e.[Enrolment Date] is null and x.derived_enrolment_date is not null, 1, 0) as enrolment_from_exception,
            iif(e.[Election Date]  is null and x.derived_election_date  is not null, 1, 0) as election_from_exception,
            -- the dates the source recorded, kept ONLY where moved (either
            -- direction: recorded > effective = backdated, < = moved forward)
            iif(bk.enr_moved  = 1, rd.recorded_enrolment_date, null) as recorded_enrolment_date,
            bk.enr_moved                            as enrolment_from_subs_history,
            iif(bk.elec_moved = 1, rd.recorded_election_date,  null) as recorded_election_date,
            bk.elec_moved                           as election_from_subs_history,
            -- raw contact lapse date, kept for the stale-lapse anomaly check
            cast(c.Rics_LapsedDate as date)         as contact_lapsed_date,
            -- contact-level lapse date, invalidated if the member re-enrolled/
            -- was elected since lapsing (checked against the EFFECTIVE dates:
            -- coalesced, then moved to the first paid year - see the header)
            iif(c.Rics_LapsedDate < dts.enrolment_date or c.Rics_LapsedDate < dts.election_date,
                null, cast(c.Rics_LapsedDate as date)) as lapsed_date,
            isnull(lr.id, 0)                        as lapse_reason_id,
            lr.reason_name                          as lapse_reason_name,
            -- MOD-018: the derived date, null where there is none (see the header)
            drd.derived_retirement_date             as retirement_date,
            lin.[ENR ID]                            as source_enr_id,
            isnull(rv.id, 0)                        as rpq_variant_id,
            -- MOD-031: country by local group, the local group and the own
            -- country, all from the one view (see the header)
            isnull(clg.country_id, 0)               as country_id,
            isnull(g.id, 0)                         as gender_id,
            isnull(clg.local_group_id, 0)           as local_group_id,
            isnull(clg.contact_country_id, 0)       as contact_country_id
        from Layercake.brnz_contact c
        left join (
            -- v6 aggregate over the staged rows (see #enr_base above)
            select
                [Contact No],
                min(enrolment_date) as [Enrolment Date],
                min(election_date)  as [Election Date]
            from #enr_base
            group by [Contact No]
        ) e
            on c.Rics_contactno = e.[Contact No]
        -- enrolment exception backfill (07): curated fallback dates for the
        -- migration-gap contacts. Maintained by module 8a
        -- (usp_load_ref_enrolment_exception), which runs immediately before
        -- this module on every silver load. superseded_at is not tested - see
        -- the header.
        left join Layercake.ref_enrolment_exception x
            on x.contact_no = c.Rics_contactno
        -- recorded dates: real enrolment rows first, exception fallback
        -- second. A real row appearing later automatically supersedes the
        -- exception.
        cross apply (select
            coalesce(e.[Enrolment Date], x.derived_enrolment_date) as recorded_enrolment_date,
            coalesce(e.[Election Date],  x.derived_election_date)  as recorded_election_date
        ) rd
        -- subs-history date correction (see the header): the recorded dates
        -- are compared with the first paid campaign year. Campaign year of a
        -- date = its year, +1 from October.
        left join #first_paid fp
            on fp.contact_no = c.Rics_contactno
        cross apply (select
            year(rd.recorded_enrolment_date) + iif(month(rd.recorded_enrolment_date) >= 10, 1, 0) as enr_cy,
            year(rd.recorded_election_date)  + iif(month(rd.recorded_election_date)  >= 10, 1, 0) as elec_cy
        ) rcy
        -- which way, if at all, the JOIN ANCHOR moves: the enrolment date
        -- where one exists, else the election date. -1 = backdated (first
        -- paid year is EARLIER than the recorded one - always evidence),
        -- +1 = moved forward (first paid year is LATER, and the recorded
        -- year is inside the payment history, so its missing payment is
        -- evidence too), 0 = stays as recorded. No first paid year at all
        -- (fp null) compares false throughout and lands on 0.
        cross apply (select
            case when fp.first_paid_cy < rcy.enr_cy  then -1
                 when fp.first_paid_cy > rcy.enr_cy  and rcy.enr_cy  >= @pay_floor_cy then 1
                 else 0 end as enr_dir,
            case when rd.recorded_enrolment_date is not null then 0   -- the enrolment is the anchor
                 when fp.first_paid_cy < rcy.elec_cy then -1
                 when fp.first_paid_cy > rcy.elec_cy and rcy.elec_cy >= @pay_floor_cy then 1
                 else 0 end as elec_anchor_dir
        ) dir
        cross apply (select
            iif(dir.enr_dir <> 0, 1, 0) as enr_moved,
            -- the election moves as the anchor (no enrolment date), or is
            -- CARRIED forward with an enrolment that moved past it - never
            -- with a backdated one, and never when it already sits on or
            -- after the new join date
            iif(   dir.elec_anchor_dir <> 0
                or (dir.enr_dir = 1 and rd.recorded_election_date < fp.join_date),
                1, 0) as elec_moved
        ) bk
        -- effective dates: each moved to the first paid year's join date
        -- where its flag above fired, else as recorded.
        cross apply (select
            iif(bk.enr_moved  = 1, fp.join_date, rd.recorded_enrolment_date) as enrolment_date,
            iif(bk.elec_moved = 1, fp.join_date, rd.recorded_election_date)  as election_date
        ) dts
        -- lineage: the #enr_base row that supplied the earliest qualifying
        -- date, tie-broken deterministically on created datetime then ENR ID.
        -- Guaranteed one row per contact, so the per-contact event derivation
        -- cannot fan out. Kept on the REAL aggregate (e), not the coalesced
        -- dates: an exception-sourced date has no enrolment row to point at,
        -- so source_enr_id stays null and rpq_variant resolves to N/A.
        outer apply (
            select top (1) v.[ENR ID], v.[Route ID]
            from #enr_base v
            where v.[Contact No] = c.Rics_contactno
              and (   (e.[Enrolment Date] is not null and v.enrolment_date = e.[Enrolment Date])
                   or (e.[Enrolment Date] is null     and v.election_date  = e.[Election Date]))
            order by v.[Created DateTime], v.[ENR ID]
        ) lin
        -- the election row that supplied the earliest election date: carries
        -- the is_rpq flag (an RPQ-flagged row wins a same-date tie) and the
        -- ENR ID used in anomaly details
        outer apply (
            select top (1) v.[ENR ID], v.is_rpq
            from #enr_base v
            where v.[Contact No]  = c.Rics_contactno
              and v.election_date = e.[Election Date]
            order by v.is_rpq desc, v.[Created DateTime], v.[ENR ID]
        ) elec
        left join Layercake.silv_ref_rpq_variant rv
            on  lin.[Route ID] = rv.variant_id
        left join #rics_record rec
            on c.Rics_contactno = rec.apuk_ricsmembershipnumber
        -- MOD-018: one row per contact, so the left join cannot fan out
        left join Layercake.vw_silv_derived_retirement_date drd
            on drd.contact_no = c.Rics_contactno
        left join Layercake.silv_ref_lapse_reason lr
            on rec.apuk_lapsecode = lr.lapse_code
        -- MOD-031: one view row per brnz_contact row, so the join cannot fan out
        left join Layercake.vw_silv_contact_local_group clg
            on clg.contact_id = c.ContactId
        left join Layercake.silv_ref_gender g
            on c.GenderCode = g.gender_code
        where c._is_deleted = 0
          and c.Rics_contactno is not null
          -- No rics record at all -> not a member by the source definition.
          -- #rics_record already holds exactly one row per membership number
          -- (test contacts removed), so a null here means brnz_rics_record
          -- carries nothing for this contact number: no grade, no lapse code,
          -- no retirement date to test. Logged as NO_RICS_RECORD by module 10.
          and rec.apuk_ricsmembershipnumber is not null
          -- Student rics-grade exclusion applied to the DRIVER: a contact
          -- whose latest membership record is Student grade produces no
          -- events at all. Null grades on a record that EXISTS are kept.
          -- OVERRIDDEN where the enrolment history shows the Student status
          -- superseded (#student_superseded above): the grade is stale, and
          -- the contact is a member-base row like any other.
          and (   isnull(rec.apuk_membergrade, 0) <> 200000003
               or exists (select 1
                          from #student_superseded ss
                          where ss.contact_no = c.Rics_contactno))
          -- No transaction history at all -> not a valid contact. A contact
          -- with no row in brnz_cust_trans has never transacted, so it is
          -- counted as neither active nor paid. No approved/settled filter
          -- here: the test is the EXISTENCE of a transaction, not whether it
          -- cleared (the payment derivation in module 7 keeps its own
          -- approved = 1 rule). Soft-deleted rows do not count - the source
          -- no longer carries them. Logged as NO_TRANSACTIONS by module 10
          -- where a valid enrolment or election exists.
          and exists (select 1
                      from Layercake.brnz_cust_trans ct
                      where ct.accountnum  = c.Rics_contactno
                        and ct._is_deleted = 0)
          and not exists (select 1
                          from Layercake.brnz_contact_test_record tst
                          where tst.contactid = c.ContactId
                            and tst._is_deleted = 0);
        set @ins = @@rowcount;

        commit;
        exec Layercake.usp_etl_log_progress @log_id, N'rebuild silv_member_base (per-contact base)', @ins, @substep_ts output;
        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, 0, @del;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, 0, @del, @err;
        throw;
    end catch
end
GO
-- Layercake.usp_load_silv_member_profile (src/sql/Layercake/Procedures/Layercake.usp_load_silv_member_profile.sql) (changed)
/*====================================================================
    Layercake.usp_load_silv_member_profile
    Silver layer - loads one table
====================================================================*/

/*====================================================================
    12. Layercake.silv_member_profile
    ------------------------------------------------------------------
    Per-contact reporting attributes for the DETAIL daily count:
    country_id, gender_id, retirement_date and (MOD-031, REQ-027)
    local_group_id and contact_country_id. Staged straight from
    silv_member_base and diff-synced on contact_no. country_id is the
    country by local group and contact_country_id the own country, as
    the member base holds them; a difference in either new column is a
    change like any other.

    WHY IT EXISTS: the state ranges don't carry these columns, so the
    range diff can never see an attribute change - without this table a
    member changing country/gender, or a retirement date arriving, would
    be completely invisible to the daily count.

    AFFECTED-DATE DERIVATION (feeds the pending-rebuild log):
      * country/gender/local group/own country changed -> the contact's
        earliest range valid_from (attributes apply day-by-day as CURRENT
        values, so the whole active history would re-bucket);
      * retirement date changed -> the EARLIER of the old and new
        retirement dates (day-level Practising/Retired status is the
        only thing that reads it).
    New contacts and deleted contacts are NOT windowed here: their
    ranges are new/removed too, so the range diff already covers them.

    Must run AFTER usp_load_silv_member_state_ranges - the affected-date
    calculation reads the ranges.
====================================================================*/
create or alter procedure Layercake.usp_load_silv_member_profile
    @run_id uniqueidentifier = null
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    declare @log_id           bigint,
            @ins              int,
            @upd              int,
            @del              int,
            @rc               int,
            @substep_ts       datetime2(3),
            @err              nvarchar(4000),
            @prof_recalc_from date;

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'silver', 'silv_member_profile', @log_id output;
        set @substep_ts = sysdatetime();
        begin tran;

        select b.contact_no, b.country_id, b.gender_id, b.retirement_date, b.local_group_id, b.contact_country_id
        into #prof_stage
        from Layercake.silv_member_base b;
        set @rc = @@rowcount;

        -- duplicate Rics_contactno fails loudly here (same philosophy as the
        -- #ev_stage PK): fix the duplicate contact, don't silently pick one
        create unique clustered index cx_prof_stage on #prof_stage (contact_no);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #prof_stage (from silv_member_base)', @rc, @substep_ts output;

        -- changed contacts, with the narrowest date each change can affect
        select
            s.contact_no,
            iif(exists (select s.country_id, s.gender_id, s.local_group_id, s.contact_country_id
                        except
                        select t.country_id, t.gender_id, t.local_group_id, t.contact_country_id), 1, 0) as demo_changed,
            case when isnull(s.retirement_date, '99991231') <> isnull(t.retirement_date, '99991231')
                 then (select min(d) from (values (s.retirement_date), (t.retirement_date)) x(d) where d is not null)
            end as retirement_changed_from
        into #prof_changed
        from #prof_stage s
        join Layercake.silv_member_profile t
          on  t.contact_no = s.contact_no
        where exists (select s.country_id, s.gender_id, s.retirement_date, s.local_group_id, s.contact_country_id
                      except
                      select t.country_id, t.gender_id, t.retirement_date, t.local_group_id, t.contact_country_id);
        set @rc = @@rowcount;

        set @prof_recalc_from = (
            select min(v.win_from)
            from (
                -- country/gender/local group: from the contact's earliest state range
                select min(r.valid_from) as win_from
                from #prof_changed ch
                join Layercake.silv_member_state_ranges r
                  on  r.contact_no = ch.contact_no
                where ch.demo_changed = 1
                union all
                -- retirement date: from the earlier of old/new dates
                select min(ch.retirement_changed_from)
                from #prof_changed ch
                where ch.retirement_changed_from is not null
            ) v
            where v.win_from is not null);
        exec Layercake.usp_etl_log_progress @log_id, N'diff: changed contacts + affected-from', @rc, @substep_ts output;

        -- diff-sync: update changed
        update tgt
        set country_id         = s.country_id,
            gender_id          = s.gender_id,
            retirement_date    = s.retirement_date,
            local_group_id     = s.local_group_id,
            contact_country_id = s.contact_country_id
        from Layercake.silv_member_profile tgt
        join #prof_changed ch on ch.contact_no = tgt.contact_no
        join #prof_stage   s  on s.contact_no  = tgt.contact_no;
        set @upd = @@rowcount;
        exec Layercake.usp_etl_log_progress @log_id, N'sync: update', @upd, @substep_ts output;

        -- insert new contacts (their dates are covered by the range diff)
        insert into Layercake.silv_member_profile
        (contact_no, country_id, gender_id, retirement_date, local_group_id, contact_country_id)
        select s.contact_no, s.country_id, s.gender_id, s.retirement_date, s.local_group_id, s.contact_country_id
        from #prof_stage s
        where not exists (select 1 from Layercake.silv_member_profile t
                          where t.contact_no = s.contact_no);
        set @ins = @@rowcount;
        exec Layercake.usp_etl_log_progress @log_id, N'sync: insert', @ins, @substep_ts output;

        -- hard-delete contacts no longer derived (test-flagged, went Student,
        -- contact soft-deleted). Their ranges are removed by the state-range
        -- module in the same run.
        delete tgt
        from Layercake.silv_member_profile tgt
        where not exists (select 1 from #prof_stage s
                          where s.contact_no = tgt.contact_no);
        set @del = @@rowcount;
        exec Layercake.usp_etl_log_progress @log_id, N'sync: delete', @del, @substep_ts output;

        -- retro-change log: only if these changes reach already-loaded dates
        exec Layercake.usp_etl_log_pending_rebuild @run_id, 'member_profile', @prof_recalc_from, @rc output;
        if @rc > 0
            exec Layercake.usp_etl_log_progress @log_id, N'retro change logged (not rebuilt) - see etl_daily_count_pending_rebuild', @rc, @substep_ts output;

        commit;
        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, @del;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, @del, @err;
        throw;
    end catch
end
GO
-- Layercake.usp_load_silv_member_state_ranges (src/sql/Layercake/Procedures/Layercake.usp_load_silv_member_state_ranges.sql) (changed)
/*====================================================================
    Layercake.usp_load_silv_member_state_ranges
    Silver layer - loads one table
====================================================================*/

/*====================================================================
    11. Layercake.silv_member_state_ranges
    ------------------------------------------------------------------
    Full re-derive into #rng_stage, then a per-contact diff-sync: only
    contacts whose range set actually changed are deleted + re-inserted.

    P2-14: the ranges derive ENTIRELY from silv_membership_events.
    Events are the single source of business rules; the ranges are just
    those events pivoted into from/to periods, so daily counts and
    event-level reporting reconcile by construction.

    State mapping:
      Join/Candidate -> 'enrolment'   Join/RPQ, Change -> 'election'
      Lapse          -> 'lapse'       Readmission -> the grade held
                                                     at readmission
      Join/Subscription -> 'enrolment'. The payment-derived Join always
      carries grade N/A (module 9: the contact has neither date), so it
      opens the non-qualified active state and orders with Candidate,
      not with the elected Joins the catch-all arm covers.

    v6 SAME-DAY ORDERING: events on the same date order as
    enrolment -> election -> lapse (-> readmission), and that per-contact
    sequence is PERSISTED in state_seq.

    REGION BY LOCAL GROUP (MOD-031, REQ-027, RULE-173, RULE-175): region
    is the member's world region (the flavour Phase 1 uses) from
    Layercake.vw_silv_contact_local_group: the usable local group's
    region, else the own country's. contact_region is always the own
    country's world region. An unknown own country (country 0) gives
    'N/K', as Phase 1 does: in contact_region always, and in region
    when the member has no usable local group (a usable group still
    gives its own region). A contact the view does not hold (no live
    brnz_contact row) keeps the Phase 1 rule from the event's country in
    both columns. A region longer than varchar(12) fails the load with
    an error naming the value; it is never cut short.

    The earliest date the changed contacts could affect goes to the
    RETRO-CHANGE LOG - it does not rebuild history.
====================================================================*/
create or alter procedure Layercake.usp_load_silv_member_state_ranges
    @run_id uniqueidentifier = null
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    declare @log_id          bigint,
            @ins             int,
            @del             int,
            @rc              int,
            @substep_ts      datetime2(3),
            @err             nvarchar(4000),
            @rng_recalc_from date,
            @long_value      nvarchar(200),
            @long_contact    nvarchar(200),
            @long_n          int,
            @long_msg        nvarchar(2048);

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'silver', 'silv_member_state_ranges', @log_id output;
        set @substep_ts = sysdatetime();
        begin tran;

        -- MOD-031: each contact's regions, one row per contact number. The view
        -- has one row per live brnz_contact row; a contact number held twice is
        -- stopped downstream (the events and profile loads fail on it), and the
        -- lowest ContactId keeps this stage deterministic meanwhile.
        select v.contact_no,
               iif(v.local_group_id = 0 and v.contact_country_id = 0, N'N/K', v.region_name) as region,
               iif(v.contact_country_id = 0, N'N/K', v.contact_region_name)                 as contact_region
        into #clg
        from (
            select l.contact_no, l.local_group_id, l.contact_country_id, l.region_name, l.contact_region_name,
                   row_number() over (partition by l.contact_no order by l.contact_id) as rn
            from Layercake.vw_silv_contact_local_group l
            where l.contact_no is not null
        ) v
        where v.rn = 1;

        create unique clustered index cx_clg on #clg (contact_no);

        -- one row per contact per state, with valid_from/valid_to bounding the
        -- period in that state. Retirement is NOT a range: Practising/Retired
        -- is a sub-status of Qualified, so retirement doesn't end an active range.
        with ev as (
            select
                e.contact_no,
                e.event_date,
                case
                    when e.event_type = 'Join' and e.event_subtype = 'Candidate' then 'enrolment'
                    -- a payment-derived Join (module 9) opens the NON-QUALIFIED
                    -- active state: it carries grade N/A by construction - the
                    -- contact has neither an enrolment nor an election date -
                    -- so the catch-all Join arm below, which reads every other
                    -- Join as an election, would assert a grade the source
                    -- does not support
                    when e.event_type = 'Join' and e.event_subtype = 'Subscription' then 'enrolment'
                    when e.event_type = 'Join'                                   then 'election'
                    when e.event_type = 'Change'                                 then 'election'
                    -- a readmitted member re-opens at the grade held at readmission
                    when e.event_type = 'Readmission' then iif(mg.grade_name = 'Qualified', 'election', 'enrolment')
                    when e.event_type = 'Lapse'                                  then 'lapse'
                end as grade,
                -- v2 parity: Region is the WORLD region name (as Gold Layer v2
                -- uses), not market_reporting_region - both stay available on
                -- silv_ref_country / dim_country. MOD-031: by local group, from
                -- the view (see the header); Phase 1's rule where it has no row.
                case when clg.contact_no is not null then clg.region
                     else iif(e.country_id = 0, 'N/K', ctry.region_name) end as region,
                case when clg.contact_no is not null then clg.contact_region
                     else iif(e.country_id = 0, 'N/K', ctry.region_name) end as contact_region,
                -- same-day ordering: enrolment < election < lapse < readmit,
                -- so a same-day lapse + readmission nets out to an active
                -- state, and a same-day enrolment + election ends the day
                -- elected (the LATEST state wins the day)
                case
                    when e.event_type = 'Join'
                     and e.event_subtype in ('Candidate', 'Subscription')        then 1
                    when e.event_type in ('Join', 'Change')                      then 2
                    when e.event_type = 'Lapse'                                  then 3
                    else 4
                end as ord
            from Layercake.silv_membership_events e
            inner join Layercake.silv_ref_country ctry
                on  e.country_id = ctry.id
            left join Layercake.silv_ref_membership_grade mg
                on  mg.id = e.grade_id
            left join #clg clg
                on  clg.contact_no = e.contact_no
            -- Renewal events don't open or close a state: they drive the paid
            -- count via silv_payment_events, not the active state ranges
            where e.event_type in ('Join', 'Change', 'Lapse', 'Readmission')
        ),
        -- distinct guards against events landing on the same
        -- contact/date/state (they would only produce zero-length duplicate
        -- ranges, but this keeps the stage clean and the diff small)
        date_list as (
            select
                v.contact_no,
                v.event_date,
                v.grade,
                v.region,
                v.contact_region,
                row_number() over (partition by v.contact_no order by v.event_date, v.ord) as id
            from (select distinct contact_no, event_date, grade, region, contact_region, ord from ev) v
        )
        -- each state runs from its own event date to the NEXT event in the
        -- sequence (null = open ended). Same-day transitions produce
        -- zero-length ranges (valid_from = valid_to) which fall out naturally
        -- in the daily-count join (half-open interval) - the day counts the
        -- latest state only.
        select
            a.contact_no,
            a.event_date as valid_from,
            b.event_date as valid_to,
            case when month(a.event_date) >= 10 then year(a.event_date) + 1 else year(a.event_date) end as campaign_year_from,
            a.grade,
            a.region,
            a.id         as state_seq,
            a.contact_region
        into #rng_stage
        from date_list a
        left join date_list b
            on  a.contact_no = b.contact_no
            and a.id = b.id - 1;
        set @rc = @@rowcount;

        create clustered index cx_rng_stage on #rng_stage (contact_no);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #rng_stage (events -> ranges)', @rc, @substep_ts output;

        -- MOD-031: a region that does not fit varchar(12) stops the load with
        -- the whole value named, rather than being cut short on insert
        select @long_n = count(*),
               @long_value = min(v.val),
               @long_contact = min(v.contact_no)
        from (select s.contact_no, s.region as val from #rng_stage s where len(s.region) > 12
              union all
              select s.contact_no, s.contact_region from #rng_stage s where len(s.contact_region) > 12) v;

        if @long_n > 0
        begin
            set @long_msg = concat(N'Region value too long for Layercake.silv_member_state_ranges (varchar(12)): ''',
                                   @long_value, N''' (contact ', @long_contact, N'; ', @long_n,
                                   N' range(s) affected). Nothing was written; correct the local group or country region and rerun.');
            throw 50031, @long_msg, 1;
        end

        -- contacts whose derived range set differs from what's stored
        -- (either direction: new/moved ranges, and ranges that disappeared).
        select contact_no
        into #rng_changed
        from (
            select contact_no from (
                select contact_no, valid_from, valid_to, campaign_year_from, grade, region, state_seq, contact_region from #rng_stage
                except
                select contact_no, valid_from, valid_to, campaign_year_from, grade, region, state_seq, contact_region from Layercake.silv_member_state_ranges
            ) a
            union
            select contact_no from (
                select contact_no, valid_from, valid_to, campaign_year_from, grade, region, state_seq, contact_region from Layercake.silv_member_state_ranges
                except
                select contact_no, valid_from, valid_to, campaign_year_from, grade, region, state_seq, contact_region from #rng_stage
            ) b
        ) v;
        set @rc = @@rowcount;

        create unique clustered index cx_rng_changed on #rng_changed (contact_no);

        -- earliest calendar date these changes can affect: min valid_from over
        -- BOTH the old rows (about to be removed) and the new rows.
        -- Informational only - it feeds the pending-rebuild log, not a
        -- recompute window.
        set @rng_recalc_from = (
            select min(v.valid_from)
            from (
                select s.valid_from
                from #rng_stage s
                join #rng_changed ch on ch.contact_no = s.contact_no
                union all
                select t.valid_from
                from Layercake.silv_member_state_ranges t
                join #rng_changed ch on ch.contact_no = t.contact_no
            ) v);
        exec Layercake.usp_etl_log_progress @log_id, N'diff: changed contacts', @rc, @substep_ts output;

        -- per-contact replace: cheap, and only touches contacts that changed
        delete tgt
        from Layercake.silv_member_state_ranges tgt
        join #rng_changed ch on ch.contact_no = tgt.contact_no;
        set @del = @@rowcount;
        exec Layercake.usp_etl_log_progress @log_id, N'sync: delete changed contacts', @del, @substep_ts output;

        insert into Layercake.silv_member_state_ranges
        (contact_no, valid_from, valid_to, campaign_year_from, grade, region, state_seq, contact_region)
        select s.contact_no, s.valid_from, s.valid_to, s.campaign_year_from, s.grade, s.region, s.state_seq, s.contact_region
        from #rng_stage s
        join #rng_changed ch on ch.contact_no = s.contact_no;
        set @ins = @@rowcount;
        exec Layercake.usp_etl_log_progress @log_id, N'sync: insert changed contacts', @ins, @substep_ts output;

        -- retro-change log: only if these changes reach already-loaded dates
        exec Layercake.usp_etl_log_pending_rebuild @run_id, 'state_ranges', @rng_recalc_from, @rc output;
        if @rc > 0
            exec Layercake.usp_etl_log_progress @log_id, N'retro change logged (not rebuilt) - see etl_daily_count_pending_rebuild', @rc, @substep_ts output;

        commit;
        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, 0, @del;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, 0, @del, @err;
        throw;
    end catch
end
GO
-- Layercake.usp_load_silv_daily_count (src/sql/Layercake/Procedures/Layercake.usp_load_silv_daily_count.sql) (changed)
/*====================================================================
    Layercake.usp_load_silv_daily_count
    Silver layer - loads one table
====================================================================*/

/*====================================================================
    13. Layercake.silv_daily_count_detail + Layercake.silv_daily_count
        (two tables, one module: see the file header)
    ------------------------------------------------------------------
    WHAT THIS MODULE LOADS (MOD-022 ADR-007, MOD-026 ADR-011): the
    daily counts, written as DIFFERENCES only. After any completed run
    the stored history, the cell counts and the adjustment rows equal
    what @FullRebuild = 1 produces on the same data.

    SEGMENT GRAIN (MOD-028, REQ-026, RULE-155 to RULE-161): a detail
    cell is [date] x region x country x gender x grade x status x
    payment method x payer type x concession type. A contact-day takes
    the three ids from its silv_member_year_attributes row for the
    day's Campaign Year (the spine's campaign_year), carried or not,
    for every grade and measure, and 0 Unknown where it has no row.
    The attributes are one row per contact and Campaign Year, so a
    contact still sits in one cell per day. silv_daily_count keeps its
    grain: it is the sum over the detail as before.

    LOCAL GROUP GRAIN (MOD-031, REQ-027, RULE-172 to RULE-178): the
    cell also carries the contact's local_group_id and contact_country_id
    (own country) from silv_member_profile and contact_region (own
    country's region) from the state range, beside country_id and
    region, which now carry the values by local group. They are one
    value per contact (and per range), so a contact still sits in one
    cell per day. They are part of the contact's inputs, so a change of
    local group, own country or a group's values alone makes the
    contact a changed contact on the normal path. The local group and
    country lists are not reference inputs.

    GUARD (RULE-145): before anything is written, every run checks that
    no contact holds two overlapping non-zero-length state ranges
    ([valid_from, valid_to), a null valid_to open-ended). If one does,
    the run fails naming the first such contact and writes nothing:
    the count rule below relies on one cell per contact per day.

    INPUTS: per contact, its rows in silv_membership_events,
    silv_member_state_ranges, silv_payment_events, silv_member_profile
    and (MOD-028) silv_member_year_attributes, limited to the columns
    read below, are fingerprinted and compared with
    Layercake.etl_daily_count_input_basis (the inputs as last applied).
    A change to any of the three attribute ids in any Campaign Year
    makes the contact a changed contact (RULE-160). The reference
    tables (ref_date_spine and ref_campaign_year_config up to the
    latest loaded date, silv_ref_membership_status in full) get one
    fingerprint each. The segment reference lists are not inputs
    (RULE-161).

    RESTATEMENT (MOD-028, ADR-013, Q-061): while the basis holds the
    'detail_grain_restatement' marker (written by the MOD-028
    migration), the run takes the full-recompute path from 2020-10-01
    and works out its adjustment rows at the OLD grain: per [date],
    region, country, gender, grade and status, the new figures summed
    over the three ids minus the stored ones, written with -2 in the
    three ids. A change of grain alone therefore writes nothing. The
    marker goes in the final transaction of the first run that
    completes; a run that fails part way keeps it.

    RESTATEMENT BY LOCAL GROUP (MOD-031, RULE-179): while the basis
    holds the 'local_group_restatement' marker (written by the MOD-031
    migration), the run takes the full-recompute path from 2020-10-01
    and works out its adjustment rows at the OWN-COUNTRY grain: region
    is replaced by contact_region, country_id by contact_country_id and
    local_group_id by -2, so the figures are compared summed over the
    local group values, and a row is written with those values. The
    change of basis alone therefore writes nothing, while a real change
    the run finds is still recorded. With both markers present, the
    three segment ids also take -2. The final transaction of the first
    run that completes removes the marker.

    TWO PATHS. Every run logs the etl_progress_log sub-steps
    'contacts_recomputed' and 'full_recompute_path' (RULE-153).
      FULL-RECOMPUTE PATH (the MOD-022 behaviour) for @FullRebuild,
      @RebuildFrom, a changed reference table, a restatement marker,
      or a snapshot not in step with the basis (some contact has a
      'contact' basis row but no etl_daily_count_applied_contact row, or
      the reverse: after deployment, or after a run that did not
      finish). Every spine date from the START DATE to today is derived
      from all contacts and written as differences. The START DATE is
      the earliest of the changed contacts' earliest affected dates (the
      start of the Campaign Year of the earliest input row, old or new,
      never before 2020-10-01), 2020-10-01 for a changed reference
      table, a marker or a snapshot out of step, the first date not
      yet loaded, today, and @RebuildFrom (2020-10-01 for @FullRebuild).
      CHANGED-CONTACTS PATH (a normal run): on the dates already loaded
      that a changed contact's inputs can reach, its contribution
      worked out from its snapshot (the etl_daily_count_applied_*
      tables) is taken out and the one from its current inputs added.
      The same derivation gives both. A cell whose contact count
      (etl_daily_count_cell_contacts) rises from 0 is inserted, one that
      falls to 0 is deleted (Q-059), and the touched silv_daily_count
      rows are brought to the sum of their detail. Dates not yet loaded
      are first-loaded from all contacts as on the full path.

    WRITES: date-ordered batches of @DailyCountBatchDays dates (default
    31), each ONE transaction with its detail and main differences, its
    adjustment rows (one per detail cell whose figures change on a date
    ALREADY MARKED in etl_daily_count_loaded, new minus old, a missing
    cell counting as 0), its cell counts and its loaded marks. A first
    load writes no adjustment. The first batch transaction also
    withdraws the changed contacts' snapshot rows (an appeared contact
    gets a header of its own instead), so a run that does not finish
    leaves the snapshot out of step and the next run takes the full
    path, which finds no differences where batches committed.

    FINAL TRANSACTION: after the last batch, the basis and the snapshot
    of the contacts this run applied (and of any out of step) are
    brought into line with the inputs the run used, the restatement
    markers are removed, and open etl_daily_count_pending_rebuild rows
    whose affected_from the start date covers are stamped applied. That
    table is a diagnostic only.

    FAILURE: committed batches stay committed and the error is
    re-raised. No cleanup.

    COUNT DERIVATION: ONE join builds the DETAIL cells, and the main
    silv_daily_count is a plain SUM over it. Each measure is the SUM of
    the contacts' 0-or-1 contributions (RULE-144, RULE-146): a contact
    occupies at most one detail cell per day (the guard, and one
    attributes row per contact and Campaign Year) and every join below
    is 1:1 against the range row, so the sums equal the Phase 1
    distinct counts. A contact contributes a contact count of 1 to its
    cell on each day it sits there, whatever its measures.

    COUNT RULE: a member counts in the LATEST state they held on any
    given day. The half-open interval join [valid_from, valid_to)
    implements this: a same-day transition leaves a zero-length range
    (matches no date), so the day lands on the last state opened that
    day - state_seq guarantees that is the last event in the
    enrolment -> election -> lapse order.

    STATUS RULE: 'election' rows split by day-level status - Retired
    from the retirement date onward, else Practising (a null retirement
    date -> Practising). 'enrolment' and 'lapse' rows carry status N/A.

    v2-parity: open-ended ranges count through today; lapsed members
    never count as Active.

    ------------------------------------------------------------------
    TWO PAID MEASURES, SIDE BY SIDE
    ------------------------------------------------------------------
    Both count contacts, both are gated by the same state-range join as
    the active count (so every driver exclusion on the active side
    removes the contact from both paid numbers too), and both are
    attributed to the cell the contact occupies on the day. They are
    NOT expected to agree - carrying both is the point.

    paid_count (PAYMENT-driven, the original, unchanged)
      A payment event for the day's campaign year whose adjusted renewal
      date is on or before the day. Reads silv_payment_events, i.e. the
      subs invoice position.

    paid_count_event (EVENT-driven, added alongside)
      Reads silv_membership_events instead: joins + renewals +
      readmissions. A contact is PAID IN from the earliest Join /
      Renewal / Readmission event in the campaign year (step e picks
      exactly one - they are already mutually exclusive per contact per
      year, since module 9 excludes the Join year and the Readmission
      years from Renewal; the tie-break only makes that deterministic),
      and stays counted for the rest of that year. Keyed on campaign
      year, so the measure resets to zero on each 1 October and builds
      through the year: on any day it is how many members have paid so
      far this campaign year.

      LAPSING DOES NOT DEDUCT. A member who paid and then lapsed still
      paid, and this measure is a count of that. Lapses are still
      derived and still reported - event_lapse_count below - they just
      do not come back off the number. That makes paid_count_event
      monotonic within a campaign year, and it is the one place it parts
      company with every other count in this module (the active count,
      and paid_count through its state-range gate, both stop at a
      lapse).

      Join here is the Join EVENT (enrolment-dated for Candidates,
      election-dated for RPQ direct entries), not a payment - which is
      the substantive difference from paid_count and the reason the two
      diverge in a member's first year.

    event_join_count / event_renewal_count / event_readmission_count are
    the daily FLOWS behind paid_count_event: the contacts whose paid-in
    fell on that day. They reconcile with the stock by construction - a
    running total of (join + renewal + readmission) from the campaign
    year start reproduces paid_count_event exactly, at the day level.
    That holds on the TOTAL, not cell by cell: the stock is attributed
    to the cell the contact sits in on the day being counted, the flow
    to the cell they sat in on the event day, and a member who moves
    country or is elected moves cell in between.

    event_lapse_count sits alongside them as a FOURTH flow, reported but
    NOT part of that identity - it is the contacts who had paid in this
    campaign year and then lapsed on that day. Two things it is not: it
    is not deducted from paid_count_event (see above), and it is not
    every lapse - a member bulk-lapsed on 1 June for never paying at all
    has no paid-in behind them and does not appear. fact_membership_
    events carries every Lapse event if the unfiltered number is wanted.

    Parameters:
      @FullRebuild         - 1 recomputes the WHOLE spine (from
                             2020-10-01) on the full-recompute path.
                             Changes are written as differences and
                             recorded as adjustments.
      @RebuildFrom         - full-recompute path from this date at the
                             latest. It can only move the start date
                             earlier. Ignored when @FullRebuild = 1.
      @DailyCountBatchDays - batch size, and the resume granularity
                             (default 31; minimum 1).
====================================================================*/
create or alter procedure Layercake.usp_load_silv_daily_count
    @run_id              uniqueidentifier = null,
    @FullRebuild         bit  = 0,
    @RebuildFrom         date = null,
    @DailyCountBatchDays int  = 31
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();
    -- null-safe: the batched walk is driven by a work list, so a null/zero
    -- batch size would select no dates and never make progress
    if isnull(@DailyCountBatchDays, 0) < 1 set @DailyCountBatchDays = 31;

    declare @log_id        bigint,
            @ins           int,
            @upd           int,
            @del           int,
            @adj           int,
            @rc            int,
            @pend          int,
            @note          nvarchar(256),
            @substep_ts    datetime2(3),
            @err           nvarchar(4000),
            @today         date = cast(getdate() as date),
            @spine_from    date = '20201001',
            -- a contact with no dated input row (a profile alone) can affect no date
            @no_date       date = '99991231',
            -- ADR-013: the basis row the MOD-028 migration writes until the
            -- stored history is restated at the segment grain
            @marker_name   varchar(64) = 'detail_grain_restatement',
            @restate       bit = 0,
            -- RULE-179: the basis row the MOD-031 migration writes until the
            -- stored history is restated at the local group values
            @lg_marker_name varchar(64) = 'local_group_restatement',
            @lg_restate    bit = 0,
            @rebuild_from  date = null,
            @start         date,
            @basis_to_now  date,
            @basis_to_end  date,
            @contacts_chg  int,
            @refs_chg      int,
            @snap_out      int,
            @full          bit = 0,
            @recomputed    int,
            @chg_from      date,
            @withdrawn     bit = 0,
            @mode          char(1),
            @guard_n       int,
            @guard_first   nvarchar(200),
            @guard_msg     nvarchar(2048),
            @win_from      date,
            @win_to        date,
            @marked        int,
            @todo_days     int,
            @todo_min      date,
            @todo_max      date;

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'silver', 'silv_daily_count', @log_id output;
        set @substep_ts = sysdatetime();

        select @ins = 0, @upd = 0, @del = 0, @adj = 0;

        /* ---- a. deliberate rebuild request ----------------------------
           @FullRebuild / @RebuildFrom take the full-recompute path and
           only move the start date earlier. No loaded marker is cleared:
           the marks decide which changes are adjustments, and a rebuild
           records its changes like any run.
           ------------------------------------------------------------- */
        if @FullRebuild = 1
            set @rebuild_from = @spine_from;
        else if @RebuildFrom is not null
            set @rebuild_from = @RebuildFrom;

        if @rebuild_from < @spine_from
            set @rebuild_from = @spine_from;

        /* ---- b. the inputs, as they stand now --------------------------
           Staged once, side 'C'. The same staging later takes the changed
           contacts' snapshot as side 'O', so one derivation (step f)
           works out both their old and their new contribution. Only the
           rows and columns the derivation reads, so a change to segment
           or amount columns on events, or to audit columns, is not an
           input change. region stays nullable here: a bad range fails its
           batch, as it always has, not the whole run. MOD-031: a missing
           own-country value (never in the NOT NULL tables, only in a
           mid-deploy state) falls back to the range's region and the
           profile's country, as the migration fills the rows it finds.
           ------------------------------------------------------------- */
        create table #rng
        (
            rn             int identity(1, 1) not null,
            side           char(1) not null,
            contact_no     nvarchar(200) collate database_default not null,
            valid_from     date not null,
            valid_to       date null,
            grade          varchar(12) collate database_default null,
            region         varchar(12) collate database_default null,
            contact_region varchar(12) collate database_default null,   -- MOD-031
            w              int not null,        -- +1 current inputs, -1 as last applied
            pick_d         bit not null         -- read by the changed-contacts batches
        );

        insert into #rng (side, contact_no, valid_from, valid_to, grade, region, contact_region, w, pick_d)
        select 'C', r.contact_no, r.valid_from, r.valid_to, r.grade, r.region, isnull(r.contact_region, r.region), 1, 0
        from Layercake.silv_member_state_ranges r;

        create clustered index cx_rng on #rng (side, contact_no);

        create table #prof
        (
            side               char(1) not null,
            contact_no         nvarchar(200) collate database_default not null,
            country_id         int null,
            gender_id          int null,
            retirement_date    date null,
            local_group_id     int null,        -- MOD-031
            contact_country_id int null,        -- MOD-031
            primary key clustered (side, contact_no)
        );

        insert into #prof (side, contact_no, country_id, gender_id, retirement_date, local_group_id, contact_country_id)
        select 'C', pr.contact_no, pr.country_id, pr.gender_id, pr.retirement_date,
               isnull(pr.local_group_id, 0), isnull(pr.contact_country_id, pr.country_id)
        from Layercake.silv_member_profile pr;

        create table #pay
        (
            side             char(1) not null,
            contact_no       nvarchar(200) collate database_default not null,
            campaign_year    int not null,
            payment_date     date null,
            renewal_date_adj date null,
            primary key clustered (side, contact_no, campaign_year)
        );

        insert into #pay (side, contact_no, campaign_year, payment_date, renewal_date_adj)
        select 'C', p.contact_no, p.campaign_year, p.payment_date, p.renewal_date_adj
        from Layercake.silv_payment_events p;

        create table #evt
        (
            side          char(1) not null,
            contact_no    nvarchar(200) collate database_default not null,
            campaign_year int null,
            event_type    varchar(20) collate database_default not null,
            event_date    date null,
            event_id      int null
        );

        insert into #evt (side, contact_no, campaign_year, event_type, event_date, event_id)
        select 'C', e.contact_no, e.campaign_year, e.event_type, e.event_date, e.event_id
        from Layercake.silv_membership_events e
        where e.event_type in ('Join', 'Renewal', 'Readmission', 'Lapse');

        create clustered index cx_evt on #evt (side, contact_no, campaign_year);

        -- MOD-028: the segment ids a contact-day takes, one row per contact and
        -- Campaign Year as the source is keyed (the carried flags, the
        -- corporate account and the audit columns are not read)
        create table #attr
        (
            side               char(1) not null,
            contact_no         nvarchar(200) collate database_default not null,
            campaign_year      int not null,
            payment_method_id  int not null,
            payer_type_id      int not null,
            concession_type_id int not null,
            primary key clustered (side, contact_no, campaign_year)
        );

        insert into #attr (side, contact_no, campaign_year, payment_method_id, payer_type_id, concession_type_id)
        select 'C', a.contact_no, a.campaign_year, a.payment_method_id, a.payer_type_id, a.concession_type_id
        from Layercake.silv_member_year_attributes a;

        /* ---- the overlapping range guard (RULE-145, Q-055) -------------
           Before anything is written, on every path. Two non-zero-length
           ranges of one contact overlap when each starts before the other
           ends; ranges that meet, and zero-length ranges, never do.
           ------------------------------------------------------------- */
        select @guard_n     = count(distinct a.contact_no),
               @guard_first = min(a.contact_no)
        from #rng a
        inner join #rng b
            on  b.side       = a.side
            and b.contact_no = a.contact_no
            and b.rn         > a.rn
        where a.side = 'C'
          and (a.valid_to is null or a.valid_to > a.valid_from)
          and (b.valid_to is null or b.valid_to > b.valid_from)
          and a.valid_from < isnull(b.valid_to, @no_date)
          and b.valid_from < isnull(a.valid_to, @no_date);

        if @guard_n > 0
        begin
            set @guard_msg = concat(N'Overlapping state ranges: contact ', @guard_first,
                                    N' holds two overlapping non-zero-length ranges in Layercake.silv_member_state_ranges (',
                                    @guard_n, N' contact(s) affected). The daily count wrote nothing; correct the ranges and rerun.');
            throw 50026, @guard_msg, 1;
        end

        create table #in_row
        (
            contact_no nvarchar(200) collate database_default not null,
            row_text   nvarchar(400) collate database_default not null,
            row_date   date null            -- the earliest date the row refers to
        );

        insert into #in_row (contact_no, row_text, row_date)
        select e.contact_no,
               concat(N'E|', e.event_type,
                      N'|', isnull(convert(nchar(10), e.event_date, 23), N'~'),
                      N'|', isnull(convert(nvarchar(11), e.campaign_year), N'~')),
               case when y.cy_start < e.event_date or e.event_date is null then y.cy_start else e.event_date end
        from #evt e
        left join Layercake.ref_campaign_year_config cfg
            on  cfg.campaign_year = e.campaign_year
        cross apply (select isnull(cfg.campaign_year_start, datefromparts(e.campaign_year - 1, 10, 1)) as cy_start) y
        where e.side = 'C'
        union all
        -- MOD-031: the range's own-country region is an input like its region
        select r.contact_no,
               concat(N'R|', isnull(convert(nchar(10), r.valid_from, 23), N'~'),
                      N'|', isnull(convert(nchar(10), r.valid_to, 23), N'~'),
                      N'|', isnull(r.grade, N'~'),
                      N'|', isnull(r.region, N'~'),
                      N'|', isnull(r.contact_region, N'~')),
               r.valid_from
        from #rng r
        where r.side = 'C'
        union all
        -- payment_date is not read by the derivation, but it is one of the
        -- payment's dates, so it can only move the earliest date back
        select p.contact_no,
               concat(N'P|', isnull(convert(nvarchar(11), p.campaign_year), N'~'),
                      N'|', isnull(convert(nchar(10), p.renewal_date_adj, 23), N'~')),
               (select min(v.d)
                from (values (p.renewal_date_adj), (p.payment_date),
                             (isnull(cfg.campaign_year_start, datefromparts(p.campaign_year - 1, 10, 1)))) v(d))
        from #pay p
        left join Layercake.ref_campaign_year_config cfg
            on  cfg.campaign_year = p.campaign_year
        where p.side = 'C'
        union all
        -- MOD-031 (RULE-178): the local group and own country are inputs like
        -- the country, so a change to either alone makes a changed contact
        select pr.contact_no,
               concat(N'F|', isnull(convert(nvarchar(11), pr.country_id), N'~'),
                      N'|', isnull(convert(nvarchar(11), pr.gender_id), N'~'),
                      N'|', isnull(convert(nchar(10), pr.retirement_date, 23), N'~'),
                      N'|', isnull(convert(nvarchar(11), pr.local_group_id), N'~'),
                      N'|', isnull(convert(nvarchar(11), pr.contact_country_id), N'~')),
               null
        from #prof pr
        where pr.side = 'C'
        union all
        -- MOD-028 (RULE-160): the attributes rows, dated by the Campaign Year
        -- they refer to
        select a.contact_no,
               concat(N'A|', a.campaign_year, N'|', a.payment_method_id,
                      N'|', a.payer_type_id, N'|', a.concession_type_id),
               isnull(cfg.campaign_year_start, datefromparts(a.campaign_year - 1, 10, 1))
        from #attr a
        left join Layercake.ref_campaign_year_config cfg
            on  cfg.campaign_year = a.campaign_year
        where a.side = 'C';
        set @rc = @@rowcount;

        -- one fingerprint per contact; sorted bytewise so the hash is the
        -- same on every run whatever the collation makes of the row text
        create table #in_cur
        (
            contact_no             nvarchar(200) collate database_default not null primary key clustered,
            input_fingerprint      varbinary(32) not null,
            earliest_affected_date date not null
        );

        insert into #in_cur (contact_no, input_fingerprint, earliest_affected_date)
        select c.contact_no,
               c.input_fingerprint,
               -- the start of the Campaign Year of the earliest input row,
               -- never before 2020-10-01 (the ranges gate every figure, so a
               -- contact with no dated row can affect no date)
               case when c.first_date is null        then @no_date
                    when c.first_date < @spine_from then @spine_from
                    else isnull((select min(cfg.campaign_year_start)
                                 from Layercake.ref_campaign_year_config cfg
                                 where c.first_date between cfg.campaign_year_start and cfg.campaign_year_end),
                                datefromparts(year(c.first_date) - iif(month(c.first_date) < 10, 1, 0), 10, 1))
               end
        from (
            select x.contact_no,
                   cast(hashbytes('SHA2_256',
                        cast(string_agg(cast(x.row_text as nvarchar(max)), nchar(30))
                             within group (order by x.row_text collate Latin1_General_BIN2) as nvarchar(max)))
                        as varbinary(32)) as input_fingerprint,
                   min(x.row_date) as first_date
            from #in_row x
            group by x.contact_no
        ) c;

        -- the reference tables. The spine and the Campaign Year list are
        -- compared only up to the latest loaded date, so the daily extension
        -- of the spine is not a change. fp_now is compared with the basis;
        -- fp_end is what the basis will hold once this run has loaded every
        -- spine date up to today.
        select @basis_to_now = isnull(max(l.[date]), '00010101')
        from Layercake.etl_daily_count_loaded l;

        select @basis_to_end = max(x.d)
        from (select max(s.[date]) as d
              from Layercake.ref_date_spine s
              where s.[date] between @spine_from and @today
              union all
              select max(l.[date])
              from Layercake.etl_daily_count_loaded l
              where l.[date] <= @today) x;
        set @basis_to_end = isnull(@basis_to_end, '00010101');

        create table #ref_cur
        (
            input_name varchar(64) collate database_default not null primary key clustered,
            fp_now     varbinary(32) not null,
            fp_end     varbinary(32) not null
        );

        insert into #ref_cur (input_name, fp_now, fp_end)
        select v.input_name,
               cast(hashbytes('SHA2_256', isnull(cast(
                    string_agg(case when v.ref_date <= @basis_to_now then cast(v.row_text as nvarchar(max)) end, nchar(30))
                    within group (order by v.sort_key) as nvarchar(max)), N'')) as varbinary(32)),
               cast(hashbytes('SHA2_256', isnull(cast(
                    string_agg(case when v.ref_date <= @basis_to_end then cast(v.row_text as nvarchar(max)) end, nchar(30))
                    within group (order by v.sort_key) as nvarchar(max)), N'')) as varbinary(32))
        from (
            -- one sort key for both aggregates (they must share an ordering)
            select u.input_name, u.ref_date, u.row_text, u.row_text collate Latin1_General_BIN2 as sort_key
            from (
                select cast('ref_date_spine' as varchar(64)),
                       s.[date],
                       concat(convert(nchar(10), s.[date], 23), N'|', s.campaign_year, N'|', s.campaign_quarter)
                from Layercake.ref_date_spine s
                where s.[date] >= @spine_from
                union all
                select 'ref_campaign_year_config',
                       c.campaign_year_start,
                       concat(c.campaign_year, N'|', convert(nchar(10), c.campaign_year_start, 23),
                              N'|', convert(nchar(10), c.campaign_year_end, 23))
                from Layercake.ref_campaign_year_config c
                union all
                -- read in full: dated before any cutoff
                select 'silv_ref_membership_status',
                       cast('00010101' as date),
                       concat(ms.id, N'|', ms.status_name)
                from Layercake.silv_ref_membership_status ms
            ) u (input_name, ref_date, row_text)
        ) v
        group by v.input_name;

        set @note = concat(N'inputs fingerprinted: ', @rc, N' input row(s), ',
                           (select count(*) from #in_cur), N' contact(s)');
        exec Layercake.usp_etl_log_progress @log_id, @note, @rc, @substep_ts output;

        /* ---- c. changed inputs, the path and the start date ------------ */
        -- a contact whose inputs changed, appeared or disappeared, with the
        -- earlier of its old and new earliest affected dates
        create table #chg
        (
            contact_no    nvarchar(200) collate database_default not null primary key clustered,
            in_basis      bit not null,
            affected_from date not null
        );

        insert into #chg (contact_no, in_basis, affected_from)
        select isnull(c.contact_no, b.input_key),
               iif(b.input_key is null, 0, 1),
               case when b.input_key is null   then c.earliest_affected_date
                    when c.contact_no is null  then b.earliest_affected_date
                    when b.earliest_affected_date < c.earliest_affected_date then b.earliest_affected_date
                    else c.earliest_affected_date
               end
        from #in_cur c
        full join (select ib.input_key, ib.input_fingerprint, ib.earliest_affected_date
                   from Layercake.etl_daily_count_input_basis ib
                   where ib.input_name = 'contact') b
            on  b.input_key = c.contact_no
        where b.input_key is null
           or c.contact_no is null
           or b.input_fingerprint <> c.input_fingerprint;
        set @contacts_chg = @@rowcount;

        select @chg_from = min(ch.affected_from) from #chg ch;

        -- a changed reference table reaches every date (the restatement
        -- markers are not reference tables)
        select @refs_chg = count(*)
        from #ref_cur r
        full join (select ib.input_name, ib.input_fingerprint
                   from Layercake.etl_daily_count_input_basis ib
                   where ib.input_name <> 'contact'
                     and ib.input_name <> @marker_name
                     and ib.input_name <> @lg_marker_name) b
            on  b.input_name = r.input_name
        where b.input_name is null
           or r.input_name is null
           or b.input_fingerprint <> r.fp_now;

        -- ADR-013: stored history not yet restated at the segment grain
        if exists (select 1 from Layercake.etl_daily_count_input_basis ib where ib.input_name = @marker_name)
            set @restate = 1;

        -- RULE-179: stored history not yet restated at the local group values
        if exists (select 1 from Layercake.etl_daily_count_input_basis ib where ib.input_name = @lg_marker_name)
            set @lg_restate = 1;

        -- the snapshot is in step with the basis when both hold the same
        -- contacts; otherwise the stored figures may not be what the
        -- snapshot describes, and only a full recompute is safe
        create table #snap_out (contact_no nvarchar(200) collate database_default not null primary key clustered);

        insert into #snap_out (contact_no)
        select b.input_key
        from Layercake.etl_daily_count_input_basis b
        where b.input_name = 'contact'
          and not exists (select 1 from Layercake.etl_daily_count_applied_contact h where h.contact_no = b.input_key)
        union
        select h.contact_no
        from Layercake.etl_daily_count_applied_contact h
        where not exists (select 1 from Layercake.etl_daily_count_input_basis b
                          where b.input_name = 'contact'
                            and b.input_key  = h.contact_no);
        set @snap_out = @@rowcount;

        if @rebuild_from is not null or @refs_chg > 0 or @snap_out > 0 or @restate = 1 or @lg_restate = 1
            set @full = 1;

        select @start = min(x.d)
        from (select @chg_from as d
              union all
              select @spine_from where @refs_chg > 0 or @snap_out > 0 or @restate = 1 or @lg_restate = 1
              union all
              -- the first date not yet loaded (a new day, or a gap left behind)
              select min(s.[date])
              from Layercake.ref_date_spine s
              where s.[date] between @spine_from and @today
                and not exists (select 1 from Layercake.etl_daily_count_loaded l
                                where l.[date] = s.[date])
              union all
              select @today
              union all
              select @rebuild_from) x;

        if @start < @spine_from
            set @start = @spine_from;

        set @note = concat(N'changed inputs: ', @contacts_chg, N' contact(s), ', @refs_chg, N' reference table(s), ',
                           @snap_out, N' contact(s) out of step with the snapshot',
                           iif(@restate = 1, N'; restating at the segment grain', N''),
                           iif(@lg_restate = 1, N'; restating by local group', N''),
                           iif(@rebuild_from is not null,
                               concat(N'; rebuild requested from ', convert(nvarchar(10), @rebuild_from, 23)), N''));
        exec Layercake.usp_etl_log_progress @log_id, @note, @contacts_chg, @substep_ts output;

        -- RULE-153: on the full path every contact with inputs, current or as
        -- last applied, is recomputed
        if @full = 1
            select @recomputed = count(*)
            from (select c.contact_no from #in_cur c
                  union
                  select b.input_key from Layercake.etl_daily_count_input_basis b where b.input_name = 'contact'
                  union
                  select h.contact_no from Layercake.etl_daily_count_applied_contact h) x;
        else
            set @recomputed = @contacts_chg;

        exec Layercake.usp_etl_log_progress @log_id, N'contacts_recomputed', @recomputed, @substep_ts output;
        set @rc = cast(@full as int);
        exec Layercake.usp_etl_log_progress @log_id, N'full_recompute_path', @rc, @substep_ts output;

        /* ---- d. the work list ------------------------------------------
           mode 'F': derived from all contacts and written as differences
           (every date of the full path, and first loads on the normal
           path); mode 'D': a loaded date the changed contacts can reach.
           ------------------------------------------------------------- */
        create table #dc_todo ([date] date not null primary key clustered, mode char(1) not null);

        if @full = 1
            insert into #dc_todo ([date], mode)
            select s.[date], 'F'
            from Layercake.ref_date_spine s
            where s.[date] >= @start
              and s.[date] <= @today;
        else
            insert into #dc_todo ([date], mode)
            select s.[date], iif(l.[date] is null, 'F', 'D')
            from Layercake.ref_date_spine s
            left join Layercake.etl_daily_count_loaded l
                on  l.[date] = s.[date]
            where s.[date] between @spine_from and @today
              and (l.[date] is null or s.[date] >= @chg_from);
        set @todo_days = @@rowcount;

        select @todo_min = min([date]), @todo_max = max([date]) from #dc_todo;

        set @note = concat(iif(@full = 1, concat(N'full recompute from ', convert(nvarchar(10), @start, 23)),
                               N'changed contacts'),
                           N': ', @todo_days, N' date(s)',
                           iif(@todo_days > 0,
                               concat(N' ', convert(nvarchar(10), @todo_min, 23), N' -> ',
                                      convert(nvarchar(10), @todo_max, 23),
                                      N' in ', @DailyCountBatchDays, N'-day batches'), N''));
        exec Layercake.usp_etl_log_progress @log_id, @note, @todo_days, @substep_ts output;

        -- housekeeping: the spine runs two years ahead, so make sure nothing
        -- beyond today survives from an earlier run (and no marker with it).
        -- A removed row of a loaded date is an adjustment like any other
        -- (at the old grain, with -2, while restating; at the own-country
        -- grain with local group -2 while restating by local group).
        begin tran;
        insert into Layercake.silv_daily_count_adjustment
        (run_id, load_id, written_at, [date], region, country_id, gender_id, grade, membership_status_id,
         payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
         active_count_change, paid_count_change, paid_count_event_change, event_join_count_change,
         event_renewal_count_change, event_readmission_count_change, event_lapse_count_change)
        select @run_id, @log_id, sysdatetime(), d.[date],
               iif(@lg_restate = 1, d.contact_region, d.region), iif(@lg_restate = 1, d.contact_country_id, d.country_id),
               d.gender_id, d.grade, d.membership_status_id,
               iif(@restate = 1, -2, d.payment_method_id), iif(@restate = 1, -2, d.payer_type_id),
               iif(@restate = 1, -2, d.concession_type_id),
               iif(@lg_restate = 1, -2, d.local_group_id), d.contact_country_id, d.contact_region,
               -sum(d.active_count), -sum(d.paid_count), -sum(d.paid_count_event), -sum(d.event_join_count),
               -sum(d.event_renewal_count), -sum(d.event_readmission_count), -sum(d.event_lapse_count)
        from Layercake.silv_daily_count_detail d
        where d.[date] > @today
          and exists (select 1 from Layercake.etl_daily_count_loaded l where l.[date] = d.[date])
        group by d.[date],
                 iif(@lg_restate = 1, d.contact_region, d.region), iif(@lg_restate = 1, d.contact_country_id, d.country_id),
                 d.gender_id, d.grade, d.membership_status_id,
                 iif(@restate = 1, -2, d.payment_method_id), iif(@restate = 1, -2, d.payer_type_id),
                 iif(@restate = 1, -2, d.concession_type_id),
                 iif(@lg_restate = 1, -2, d.local_group_id), d.contact_country_id, d.contact_region
        having sum(d.active_count) <> 0 or sum(d.paid_count) <> 0 or sum(d.paid_count_event) <> 0
            or sum(d.event_join_count) <> 0 or sum(d.event_renewal_count) <> 0
            or sum(d.event_readmission_count) <> 0 or sum(d.event_lapse_count) <> 0;
        set @adj = @adj + @@rowcount;
        delete from Layercake.silv_daily_count_detail where [date] > @today;
        set @del = @del + @@rowcount;
        delete from Layercake.silv_daily_count        where [date] > @today;
        set @del = @del + @@rowcount;
        delete from Layercake.etl_daily_count_cell_contacts where [date] > @today;
        delete from Layercake.etl_daily_count_loaded  where [date] > @today;
        commit;

        -- the changed contacts' inputs as last applied, side 'O' (normal
        -- path only: the full path derives from the current inputs alone)
        if @full = 0 and @contacts_chg > 0
        begin
            update r
            set pick_d = 1
            from #rng r
            inner join #chg k
                on  k.contact_no = r.contact_no
            where r.side = 'C';

            insert into #rng (side, contact_no, valid_from, valid_to, grade, region, contact_region, w, pick_d)
            select 'O', a.contact_no, a.valid_from, a.valid_to, a.grade, a.region, a.contact_region, -1, 1
            from Layercake.etl_daily_count_applied_state_range a
            inner join #chg k
                on  k.contact_no = a.contact_no;

            insert into #prof (side, contact_no, country_id, gender_id, retirement_date, local_group_id, contact_country_id)
            select 'O', h.contact_no, h.country_id, h.gender_id, h.retirement_date, h.local_group_id, h.contact_country_id
            from Layercake.etl_daily_count_applied_contact h
            inner join #chg k
                on  k.contact_no = h.contact_no
            where h.profile_found = 1;

            insert into #pay (side, contact_no, campaign_year, payment_date, renewal_date_adj)
            select 'O', a.contact_no, a.campaign_year, null, a.renewal_date_adj
            from Layercake.etl_daily_count_applied_payment a
            inner join #chg k
                on  k.contact_no = a.contact_no;

            insert into #evt (side, contact_no, campaign_year, event_type, event_date, event_id)
            select 'O', a.contact_no, a.campaign_year, a.event_type, a.event_date, null
            from Layercake.etl_daily_count_applied_event a
            inner join #chg k
                on  k.contact_no = a.contact_no;

            insert into #attr (side, contact_no, campaign_year, payment_method_id, payer_type_id, concession_type_id)
            select 'O', a.contact_no, a.campaign_year, a.payment_method_id, a.payer_type_id, a.concession_type_id
            from Layercake.etl_daily_count_applied_attribute a
            inner join #chg k
                on  k.contact_no = a.contact_no;
        end

        /* ---- e. event-driven paid: per-contact staging -----------------
           Built ONCE for the whole run, for both sides, and read by every
           batch. Two work tables: #ev_paid is the STOCK (one row per
           contact per campaign year: the date they became paid, plus the
           date they later lapsed if they did), and #ev_day is those same
           two dates re-shaped as the daily FLOW. See the module header for
           the rule they implement - note in particular that the lapse date
           is carried for REPORTING only and never deducts from the stock.
           ------------------------------------------------------------- */

        -- e1. the paid-in event: the earliest Join / Renewal / Readmission
        -- in the campaign year. Ties on the same date break
        -- Join -> Readmission -> Renewal so the winner is deterministic
        -- across runs; in practice module 9 already makes the three
        -- mutually exclusive per contact per year. A tie of one type on
        -- one date gives the same row whichever wins, which is why the
        -- snapshot can leave event_id out.
        select v.side,
               v.contact_no,
               v.campaign_year,
               v.event_type,
               -- clamped to the campaign year start: a Renewal event falls
               -- back to the cash transaction date when renewal_date_adj is
               -- null, and that date can sit outside the year the subs
               -- position assigns it to. Clamping lands the FLOW on 1 October
               -- rather than in the previous campaign year; it cannot change
               -- the stock, which already counts such a contact from day one.
               iif(v.event_date < cfg.campaign_year_start, cfg.campaign_year_start, v.event_date) as paid_in_date
        into #ev_paid_in
        from (
            select e.side,
                   e.contact_no,
                   e.campaign_year,
                   e.event_type,
                   e.event_date,
                   row_number() over (partition by e.side, e.contact_no, e.campaign_year
                                      order by e.event_date,
                                               case e.event_type
                                                   when 'Join'        then 1
                                                   when 'Readmission' then 2
                                                   else 3                       -- Renewal
                                               end,
                                               e.event_id) as rn
            from #evt e
            where e.event_type in ('Join', 'Renewal', 'Readmission')
        ) v
        -- left joined: campaign years before the spine (CY2021) have no config
        -- row, and both tests below are written to pass when it is missing
        left join Layercake.ref_campaign_year_config cfg
            on  cfg.campaign_year = v.campaign_year
        where v.rn = 1
          -- an event dated after the campaign year ended cannot be that year's
          -- paid-in. Dropped from stock AND flow together, so the two still
          -- reconcile.
          and (cfg.campaign_year_end is null or v.event_date <= cfg.campaign_year_end);
        set @rc = @@rowcount;

        create unique clustered index cx_ev_paid_in on #ev_paid_in (side, contact_no, campaign_year);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #ev_paid_in (event-driven paid: paid-in events)', @rc, @substep_ts output;

        -- e2. the lapse that follows it. Feeds event_lapse_count only - it does
        -- not end the paid count. Module 9 keys Lapse events 'LA:' + contact_no,
        -- so there is at most one per contact - aggregated anyway so the join
        -- below stays 1:1 whatever the source does.
        select e.side,
               e.contact_no,
               e.campaign_year,
               min(e.event_date) as lapse_date
        into #ev_lapse
        from #evt e
        where e.event_type = 'Lapse'
        group by e.side, e.contact_no, e.campaign_year;
        set @rc = @@rowcount;

        create unique clustered index cx_ev_lapse on #ev_lapse (side, contact_no, campaign_year);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #ev_lapse (event-driven paid: lapse events)', @rc, @substep_ts output;

        -- e3. the STOCK table the day-by-day count reads.
        select i.side,
               i.contact_no,
               i.campaign_year,
               i.event_type,
               i.paid_in_date,
               -- REPORTED, NOT DEDUCTED (see the module header): a lapse in the
               -- same campaign year dated on or after the paid-in event. The
               -- ordering test is what makes this "paid, then lapsed" rather
               -- than any lapse at all - a member bulk-lapsed for never paying
               -- has no paid-in behind them and nulls out here. A CASE, not a
               -- join predicate: the contact row has to survive either way.
               case when l.lapse_date >= i.paid_in_date then l.lapse_date end as lapse_date
        into #ev_paid
        from #ev_paid_in i
        left join #ev_lapse l
            on  l.side          = i.side
            and l.contact_no    = i.contact_no
            and l.campaign_year = i.campaign_year;

        create unique clustered index cx_ev_paid on #ev_paid (side, contact_no, campaign_year);

        -- e4. the FLOW table: those same two dates as one row per contact per
        -- day. Derived from #ev_paid rather than re-read from the events, so
        -- the components can only ever describe the stock above. A contact who
        -- paid in and lapsed on the same day collapses into a single row
        -- carrying both flags - paid-in and lapse are reported independently,
        -- so neither cancels the other.
        select f.side,
               f.contact_no,
               f.event_date,
               max(f.join_flag)        as join_flag,
               max(f.renewal_flag)     as renewal_flag,
               max(f.readmission_flag) as readmission_flag,
               max(f.lapse_flag)       as lapse_flag
        into #ev_day
        from (
            select p.side,
                   p.contact_no,
                   p.paid_in_date as event_date,
                   iif(p.event_type = 'Join', 1, 0)        as join_flag,
                   iif(p.event_type = 'Renewal', 1, 0)     as renewal_flag,
                   iif(p.event_type = 'Readmission', 1, 0) as readmission_flag,
                   0                                       as lapse_flag
            from #ev_paid p
            union all
            select p.side, p.contact_no, p.lapse_date, 0, 0, 0, 1
            from #ev_paid p
            where p.lapse_date is not null
        ) f
        group by f.side, f.contact_no, f.event_date;
        set @rc = @@rowcount;

        create unique clustered index cx_ev_day on #ev_day (side, contact_no, event_date);
        exec Layercake.usp_etl_log_progress @log_id, N'stage #ev_paid + #ev_day (event-driven paid: stock and daily flow)', @rc, @substep_ts output;

        /* ---- f. the batched walk -------------------------------------- */
        create table #dc_chunk ([date] date not null primary key clustered);

        -- a batch's cells as derived now (mode F), or the changed contacts'
        -- new minus old contributions (mode D), in the target tables' shape
        create table #dc_new
        (
            [date]                  date not null,
            campaign_year           int not null,
            campaign_quarter        char(2) collate database_default not null,
            region                  varchar(12) collate database_default not null,
            country_id              int not null,
            gender_id               int not null,
            grade                   varchar(12) collate database_default not null,
            membership_status_id    int not null,
            payment_method_id       int not null,
            payer_type_id           int not null,
            concession_type_id      int not null,
            local_group_id          int not null,
            contact_country_id      int not null,
            contact_region          varchar(12) collate database_default not null,
            active_count            int not null,
            paid_count              int not null,
            paid_count_event        int not null,
            event_join_count        int not null,
            event_renewal_count     int not null,
            event_readmission_count int not null,
            event_lapse_count       int not null,
            contact_count           int not null,
            primary key clustered ([date], region, country_id, gender_id, grade, membership_status_id,
                                   payment_method_id, payer_type_id, concession_type_id,
                                   local_group_id, contact_country_id, contact_region)
        );

        create table #dc_new_main
        (
            [date]                  date not null,
            campaign_year           int not null,
            campaign_quarter        char(2) collate database_default not null,
            region                  varchar(12) collate database_default not null,
            grade                   varchar(12) collate database_default not null,
            active_count            int not null,
            paid_count              int not null,
            paid_count_event        int not null,
            event_join_count        int not null,
            event_renewal_count     int not null,
            event_readmission_count int not null,
            event_lapse_count       int not null,
            primary key clustered ([date], region, grade)
        );

        -- mode D: each touched cell, stored before and after the change
        create table #dc_apply
        (
            [date]               date not null,
            campaign_year        int not null,
            campaign_quarter     char(2) collate database_default not null,
            region               varchar(12) collate database_default not null,
            country_id           int not null,
            gender_id            int not null,
            grade                varchar(12) collate database_default not null,
            membership_status_id int not null,
            payment_method_id    int not null,
            payer_type_id        int not null,
            concession_type_id   int not null,
            local_group_id       int not null,
            contact_country_id   int not null,
            contact_region       varchar(12) collate database_default not null,
            detail_found         bit not null,
            count_found          bit not null,
            contact_count        int not null,
            old_active           int not null,
            old_paid             int not null,
            old_paid_event       int not null,
            old_join             int not null,
            old_renewal          int not null,
            old_readmission      int not null,
            old_lapse            int not null,
            new_active           int not null,
            new_paid             int not null,
            new_paid_event       int not null,
            new_join             int not null,
            new_renewal          int not null,
            new_readmission      int not null,
            new_lapse            int not null,
            primary key clustered ([date], region, country_id, gender_id, grade, membership_status_id,
                                   payment_method_id, payer_type_id, concession_type_id,
                                   local_group_id, contact_country_id, contact_region)
        );

        create table #dc_touch
        (
            [date] date not null,
            region varchar(12) collate database_default not null,
            grade  varchar(12) collate database_default not null,
            primary key clustered ([date], region, grade)
        );

        while exists (select 1 from #dc_todo)
        begin
            delete from #dc_chunk;

            -- one mode per batch, dates in order
            select top (1) @mode = t.mode from #dc_todo t order by t.[date];

            insert into #dc_chunk ([date])
            select top (@DailyCountBatchDays) t.[date]
            from #dc_todo t
            where t.mode = @mode
            order by t.[date];

            -- forward-progress guard: a batch that picked up nothing would
            -- delete nothing from #dc_todo and spin forever
            if @@rowcount = 0 break;

            select @win_from = min([date]), @win_to = max([date]) from #dc_chunk;

            -- ---- derive the batch (the Phase 1 derivation, unchanged) ----
            -- the batch's dates drive one row per day per populated cell,
            -- joining the state ranges active on that day (set-based - no
            -- cursor). Profile left-joined: every ranged contact has a
            -- profile row (both derive from silv_member_base), the isnulls
            -- are belt and braces for a mid-deploy state. Each measure is the
            -- sum of the contacts' 0-or-1 contributions, weighted -1 for a
            -- changed contact's inputs as last applied (mode D). The segment
            -- ids come from the attributes row of the day's Campaign Year,
            -- 0 Unknown where there is none (MOD-028, RULE-156). The local
            -- group and own country come from the profile and the own-country
            -- region from the range (MOD-031).
            truncate table #dc_new;

            insert into #dc_new
            ([date], campaign_year, campaign_quarter, region, country_id, gender_id, grade, membership_status_id,
             payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
             active_count, paid_count, paid_count_event,
             event_join_count, event_renewal_count, event_readmission_count, event_lapse_count, contact_count)
            select
                s.[date],
                s.campaign_year,
                s.campaign_quarter,
                r.region,
                isnull(pr.country_id, 0)          as country_id,
                isnull(pr.gender_id, 0)           as gender_id,
                r.grade,
                isnull(ms.id, 0)                  as membership_status_id,
                isnull(ya.payment_method_id, 0)  as payment_method_id,
                isnull(ya.payer_type_id, 0)      as payer_type_id,
                isnull(ya.concession_type_id, 0) as concession_type_id,
                isnull(pr.local_group_id, 0)     as local_group_id,
                isnull(pr.contact_country_id, 0) as contact_country_id,
                r.contact_region,
                -- v2 parity: lapsed members NEVER count as active - the lapse
                -- rows remain (carrying paid counts) but contribute 0 to
                -- the active count from the lapse date onward
                sum(r.w * iif(r.grade = 'lapse', 0, 1)) as active_count,
                -- PAYMENT-driven paid: a payment event exists for the campaign
                -- year with an adjusted renewal date on or before this date (the
                -- adjusted date is always inside the campaign year, which is
                -- what makes day-by-day processing valid)
                sum(r.w * iif(p.renewal_date_adj <= s.[date], 1, 0)) as paid_count,
                -- EVENT-driven paid (STOCK): paid from the campaign year's
                -- paid-in event, and counted for the rest of that year. A later
                -- lapse does NOT take it back off - the lapse date staged in
                -- step e reaches event_lapse_count below and nothing else. See
                -- the module header.
                sum(r.w * iif(ep.paid_in_date <= s.[date], 1, 0)) as paid_count_event,
                -- ...and the daily FLOWS it is built from, one per contact per
                -- day (#ev_day is unique on contact and date)
                sum(r.w * isnull(ed.join_flag, 0))        as event_join_count,
                sum(r.w * isnull(ed.renewal_flag, 0))     as event_renewal_count,
                sum(r.w * isnull(ed.readmission_flag, 0)) as event_readmission_count,
                -- reported, but deliberately NOT part of the stock above
                sum(r.w * isnull(ed.lapse_flag, 0))       as event_lapse_count,
                sum(r.w)                                  as contact_count
            from #dc_chunk c
            inner join Layercake.ref_date_spine s
                on  s.[date] = c.[date]
            inner join #rng r
                -- LATEST-STATE-PER-DAY rule: half-open interval
                -- [valid_from, valid_to). Open-ended ranges (valid_to null,
                -- i.e. currently-active members) count through today.
                -- Zero-length ranges (same-day transitions, ordered by
                -- state_seq) match no date at all.
                on  s.[date] >= r.valid_from
                and s.[date] <  isnull(r.valid_to, dateadd(day, 1, @today))
            left join #prof pr
                on  pr.side       = r.side
                and pr.contact_no = r.contact_no
            -- day-level status: Qualified members are Retired from the
            -- retirement date onward, else Practising (null retirement ->
            -- Practising via the IIF); Candidate/Lapsed rows are N/A (id 0)
            left join Layercake.silv_ref_membership_status ms
                on  ms.status_name = case when r.grade = 'election'
                                          then iif(pr.retirement_date <= s.[date], 'Retired', 'Practising')
                                          else 'N/A' end
            left join #pay p
                on  p.side          = r.side
                and p.contact_no    = r.contact_no
                and p.campaign_year = s.campaign_year
            -- event-driven paid, both halves keyed 1:1 against the range row
            -- (step e indexes them uniquely), so neither can fan the join out
            left join #ev_paid ep
                on  ep.side          = r.side
                and ep.contact_no    = r.contact_no
                and ep.campaign_year = s.campaign_year
            left join #ev_day ed
                on  ed.side       = r.side
                and ed.contact_no = r.contact_no
                and ed.event_date = s.[date]
            -- the day's segment cell: keyed 1:1 on contact and Campaign Year
            left join #attr ya
                on  ya.side          = r.side
                and ya.contact_no    = r.contact_no
                and ya.campaign_year = s.campaign_year
            where (@mode = 'F' and r.side = 'C')
               or (@mode = 'D' and r.pick_d = 1)
            group by
                s.[date], s.campaign_year, s.campaign_quarter,
                r.region, isnull(pr.country_id, 0), isnull(pr.gender_id, 0),
                r.grade, isnull(ms.id, 0),
                isnull(ya.payment_method_id, 0), isnull(ya.payer_type_id, 0), isnull(ya.concession_type_id, 0),
                isnull(pr.local_group_id, 0), isnull(pr.contact_country_id, 0), r.contact_region
            -- mode D keeps only the cells the changed contacts change
            having @mode = 'F'
                or sum(r.w) <> 0
                or sum(r.w * iif(r.grade = 'lapse', 0, 1)) <> 0
                or sum(r.w * iif(p.renewal_date_adj <= s.[date], 1, 0)) <> 0
                or sum(r.w * iif(ep.paid_in_date <= s.[date], 1, 0)) <> 0
                or sum(r.w * isnull(ed.join_flag, 0)) <> 0
                or sum(r.w * isnull(ed.renewal_flag, 0)) <> 0
                or sum(r.w * isnull(ed.readmission_flag, 0)) <> 0
                or sum(r.w * isnull(ed.lapse_flag, 0)) <> 0
            option (recompile);
            set @rc = @@rowcount;

            begin tran;

            -- ---- the first batch transaction withdraws the snapshot ------
            -- of the contacts this run applies: from now until the final
            -- transaction the snapshot is out of step with the basis, so a
            -- run that does not finish sends the next one down the full path.
            -- A contact that appeared has nothing to withdraw; a header of its
            -- own, with no basis row yet, puts the snapshot out of step the
            -- same way.
            if @withdrawn = 0
            begin
                delete a
                from Layercake.etl_daily_count_applied_state_range a
                inner join #chg k on k.contact_no = a.contact_no;

                delete a
                from Layercake.etl_daily_count_applied_payment a
                inner join #chg k on k.contact_no = a.contact_no;

                delete a
                from Layercake.etl_daily_count_applied_event a
                inner join #chg k on k.contact_no = a.contact_no;

                delete a
                from Layercake.etl_daily_count_applied_attribute a
                inner join #chg k on k.contact_no = a.contact_no;

                delete h
                from Layercake.etl_daily_count_applied_contact h
                inner join #chg k on k.contact_no = h.contact_no;

                insert into Layercake.etl_daily_count_applied_contact
                (contact_no, profile_found, country_id, gender_id, retirement_date, local_group_id, contact_country_id,
                 run_id, updated_at)
                select k.contact_no, iif(pr.contact_no is null, 0, 1), pr.country_id, pr.gender_id, pr.retirement_date,
                       pr.local_group_id, pr.contact_country_id, @run_id, sysdatetime()
                from #chg k
                left join #prof pr
                    on  pr.side       = 'C'
                    and pr.contact_no = k.contact_no
                where k.in_basis = 0;
            end

            if @mode = 'F'
            begin
                -- main: plain aggregate of the batch's detail (additive: one
                -- detail cell per contact per day - see header)
                truncate table #dc_new_main;

                insert into #dc_new_main
                ([date], campaign_year, campaign_quarter, region, grade,
                 active_count, paid_count, paid_count_event,
                 event_join_count, event_renewal_count, event_readmission_count, event_lapse_count)
                select
                    n.[date], n.campaign_year, n.campaign_quarter, n.region, n.grade,
                    sum(n.active_count), sum(n.paid_count), sum(n.paid_count_event),
                    sum(n.event_join_count), sum(n.event_renewal_count),
                    sum(n.event_readmission_count), sum(n.event_lapse_count)
                from #dc_new n
                group by n.[date], n.campaign_year, n.campaign_quarter, n.region, n.grade;

                -- ---- adjustment history (REQ-019) -----------------------
                -- one row per detail cell whose figures change on a date
                -- already marked loaded; a missing cell counts as 0 on its
                -- side. While restating (ADR-013, Q-061) both sides are summed
                -- over the three segment ids and the row carries -2 in them;
                -- while restating by local group (RULE-179) both sides are
                -- summed at the own-country grain (region := contact_region,
                -- country_id := contact_country_id, local_group_id := -2). So
                -- a change of grain or basis alone records nothing.
                insert into Layercake.silv_daily_count_adjustment
                (run_id, load_id, written_at, [date], region, country_id, gender_id, grade, membership_status_id,
                 payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
                 active_count_change, paid_count_change, paid_count_event_change, event_join_count_change,
                 event_renewal_count_change, event_readmission_count_change, event_lapse_count_change)
                select @run_id, @log_id, sysdatetime(),
                       x.[date], x.region, x.country_id, x.gender_id, x.grade, x.membership_status_id,
                       x.payment_method_id, x.payer_type_id, x.concession_type_id,
                       x.local_group_id, x.contact_country_id, x.contact_region,
                       x.active_change, x.paid_change, x.paid_event_change, x.join_change,
                       x.renewal_change, x.readmission_change, x.lapse_change
                from (
                    select isnull(n.[date], o.[date])                             as [date],
                           isnull(n.region, o.region)                             as region,
                           isnull(n.country_id, o.country_id)                     as country_id,
                           isnull(n.gender_id, o.gender_id)                       as gender_id,
                           isnull(n.grade, o.grade)                               as grade,
                           isnull(n.membership_status_id, o.membership_status_id) as membership_status_id,
                           isnull(n.payment_method_id, o.payment_method_id)       as payment_method_id,
                           isnull(n.payer_type_id, o.payer_type_id)               as payer_type_id,
                           isnull(n.concession_type_id, o.concession_type_id)     as concession_type_id,
                           isnull(n.local_group_id, o.local_group_id)             as local_group_id,
                           isnull(n.contact_country_id, o.contact_country_id)     as contact_country_id,
                           isnull(n.contact_region, o.contact_region)             as contact_region,
                           isnull(n.active_count, 0)            - isnull(o.active_count, 0)            as active_change,
                           isnull(n.paid_count, 0)              - isnull(o.paid_count, 0)              as paid_change,
                           isnull(n.paid_count_event, 0)        - isnull(o.paid_count_event, 0)        as paid_event_change,
                           isnull(n.event_join_count, 0)        - isnull(o.event_join_count, 0)        as join_change,
                           isnull(n.event_renewal_count, 0)     - isnull(o.event_renewal_count, 0)     as renewal_change,
                           isnull(n.event_readmission_count, 0) - isnull(o.event_readmission_count, 0) as readmission_change,
                           isnull(n.event_lapse_count, 0)       - isnull(o.event_lapse_count, 0)       as lapse_change
                    from (select b.[date],
                                 iif(@lg_restate = 1, b.contact_region, b.region)         as region,
                                 iif(@lg_restate = 1, b.contact_country_id, b.country_id) as country_id,
                                 b.gender_id, b.grade, b.membership_status_id,
                                 iif(@restate = 1, -2, b.payment_method_id)  as payment_method_id,
                                 iif(@restate = 1, -2, b.payer_type_id)      as payer_type_id,
                                 iif(@restate = 1, -2, b.concession_type_id) as concession_type_id,
                                 iif(@lg_restate = 1, -2, b.local_group_id)  as local_group_id,
                                 b.contact_country_id, b.contact_region,
                                 sum(b.active_count) as active_count, sum(b.paid_count) as paid_count,
                                 sum(b.paid_count_event) as paid_count_event, sum(b.event_join_count) as event_join_count,
                                 sum(b.event_renewal_count) as event_renewal_count,
                                 sum(b.event_readmission_count) as event_readmission_count,
                                 sum(b.event_lapse_count) as event_lapse_count
                          from #dc_new b
                          group by b.[date],
                                   iif(@lg_restate = 1, b.contact_region, b.region),
                                   iif(@lg_restate = 1, b.contact_country_id, b.country_id),
                                   b.gender_id, b.grade, b.membership_status_id,
                                   iif(@restate = 1, -2, b.payment_method_id), iif(@restate = 1, -2, b.payer_type_id),
                                   iif(@restate = 1, -2, b.concession_type_id),
                                   iif(@lg_restate = 1, -2, b.local_group_id), b.contact_country_id, b.contact_region) n
                    full join (select d.[date],
                                      iif(@lg_restate = 1, d.contact_region, d.region)         as region,
                                      iif(@lg_restate = 1, d.contact_country_id, d.country_id) as country_id,
                                      d.gender_id, d.grade, d.membership_status_id,
                                      iif(@restate = 1, -2, d.payment_method_id)  as payment_method_id,
                                      iif(@restate = 1, -2, d.payer_type_id)      as payer_type_id,
                                      iif(@restate = 1, -2, d.concession_type_id) as concession_type_id,
                                      iif(@lg_restate = 1, -2, d.local_group_id)  as local_group_id,
                                      d.contact_country_id, d.contact_region,
                                      sum(d.active_count) as active_count, sum(d.paid_count) as paid_count,
                                      sum(d.paid_count_event) as paid_count_event, sum(d.event_join_count) as event_join_count,
                                      sum(d.event_renewal_count) as event_renewal_count,
                                      sum(d.event_readmission_count) as event_readmission_count,
                                      sum(d.event_lapse_count) as event_lapse_count
                               from Layercake.silv_daily_count_detail d
                               inner join #dc_chunk c on c.[date] = d.[date]
                               group by d.[date],
                                        iif(@lg_restate = 1, d.contact_region, d.region),
                                        iif(@lg_restate = 1, d.contact_country_id, d.country_id),
                                        d.gender_id, d.grade, d.membership_status_id,
                                        iif(@restate = 1, -2, d.payment_method_id), iif(@restate = 1, -2, d.payer_type_id),
                                        iif(@restate = 1, -2, d.concession_type_id),
                                        iif(@lg_restate = 1, -2, d.local_group_id), d.contact_country_id, d.contact_region) o
                        on  o.[date]               = n.[date]
                        and o.region               = n.region
                        and o.country_id           = n.country_id
                        and o.gender_id            = n.gender_id
                        and o.grade                = n.grade
                        and o.membership_status_id = n.membership_status_id
                        and o.payment_method_id    = n.payment_method_id
                        and o.payer_type_id        = n.payer_type_id
                        and o.concession_type_id   = n.concession_type_id
                        and o.local_group_id       = n.local_group_id
                        and o.contact_country_id   = n.contact_country_id
                        and o.contact_region       = n.contact_region
                ) x
                where exists (select 1 from Layercake.etl_daily_count_loaded l where l.[date] = x.[date])
                  and (x.active_change <> 0 or x.paid_change <> 0 or x.paid_event_change <> 0 or x.join_change <> 0
                       or x.renewal_change <> 0 or x.readmission_change <> 0 or x.lapse_change <> 0);
                set @adj = @adj + @@rowcount;

                -- ---- detail: differences only ---------------------------
                -- restricted to the batch's OWN dates (not the from/to range)
                delete d
                from Layercake.silv_daily_count_detail d
                inner join #dc_chunk c
                    on  c.[date] = d.[date]
                where not exists (select 1 from #dc_new n
                                  where n.[date]               = d.[date]
                                    and n.region               = d.region
                                    and n.country_id           = d.country_id
                                    and n.gender_id            = d.gender_id
                                    and n.grade                = d.grade
                                    and n.membership_status_id = d.membership_status_id
                                    and n.payment_method_id    = d.payment_method_id
                                    and n.payer_type_id        = d.payer_type_id
                                    and n.concession_type_id   = d.concession_type_id
                                    and n.local_group_id       = d.local_group_id
                                    and n.contact_country_id   = d.contact_country_id
                                    and n.contact_region       = d.contact_region);
                set @del = @del + @@rowcount;

                update d
                set campaign_year           = n.campaign_year,
                    campaign_quarter        = n.campaign_quarter,
                    active_count            = n.active_count,
                    paid_count              = n.paid_count,
                    paid_count_event        = n.paid_count_event,
                    event_join_count        = n.event_join_count,
                    event_renewal_count     = n.event_renewal_count,
                    event_readmission_count = n.event_readmission_count,
                    event_lapse_count       = n.event_lapse_count
                from Layercake.silv_daily_count_detail d
                inner join #dc_new n
                    on  n.[date]               = d.[date]
                    and n.region               = d.region
                    and n.country_id           = d.country_id
                    and n.gender_id            = d.gender_id
                    and n.grade                = d.grade
                    and n.membership_status_id = d.membership_status_id
                    and n.payment_method_id    = d.payment_method_id
                    and n.payer_type_id        = d.payer_type_id
                    and n.concession_type_id   = d.concession_type_id
                    and n.local_group_id       = d.local_group_id
                    and n.contact_country_id   = d.contact_country_id
                    and n.contact_region       = d.contact_region
                where d.campaign_year           <> n.campaign_year
                   or d.campaign_quarter        <> n.campaign_quarter
                   or d.active_count            <> n.active_count
                   or d.paid_count              <> n.paid_count
                   or d.paid_count_event        <> n.paid_count_event
                   or d.event_join_count        <> n.event_join_count
                   or d.event_renewal_count     <> n.event_renewal_count
                   or d.event_readmission_count <> n.event_readmission_count
                   or d.event_lapse_count       <> n.event_lapse_count;
                set @upd = @upd + @@rowcount;

                insert into Layercake.silv_daily_count_detail
                ([date], campaign_year, campaign_quarter, region, country_id, gender_id, grade, membership_status_id,
                 payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
                 active_count, paid_count, paid_count_event,
                 event_join_count, event_renewal_count, event_readmission_count, event_lapse_count)
                select n.[date], n.campaign_year, n.campaign_quarter, n.region, n.country_id, n.gender_id, n.grade,
                       n.membership_status_id, n.payment_method_id, n.payer_type_id, n.concession_type_id,
                       n.local_group_id, n.contact_country_id, n.contact_region,
                       n.active_count, n.paid_count, n.paid_count_event,
                       n.event_join_count, n.event_renewal_count, n.event_readmission_count, n.event_lapse_count
                from #dc_new n
                where not exists (select 1 from Layercake.silv_daily_count_detail d
                                  where d.[date]               = n.[date]
                                    and d.region               = n.region
                                    and d.country_id           = n.country_id
                                    and d.gender_id            = n.gender_id
                                    and d.grade                = n.grade
                                    and d.membership_status_id = n.membership_status_id
                                    and d.payment_method_id    = n.payment_method_id
                                    and d.payer_type_id        = n.payer_type_id
                                    and d.concession_type_id   = n.concession_type_id
                                    and d.local_group_id       = n.local_group_id
                                    and d.contact_country_id   = n.contact_country_id
                                    and d.contact_region       = n.contact_region);
                set @ins = @ins + @@rowcount;

                -- ---- cell contact counts: differences only --------------
                delete cc
                from Layercake.etl_daily_count_cell_contacts cc
                inner join #dc_chunk c
                    on  c.[date] = cc.[date]
                where not exists (select 1 from #dc_new n
                                  where n.[date]               = cc.[date]
                                    and n.region               = cc.region
                                    and n.country_id           = cc.country_id
                                    and n.gender_id            = cc.gender_id
                                    and n.grade                = cc.grade
                                    and n.membership_status_id = cc.membership_status_id
                                    and n.payment_method_id    = cc.payment_method_id
                                    and n.payer_type_id        = cc.payer_type_id
                                    and n.concession_type_id   = cc.concession_type_id
                                    and n.local_group_id       = cc.local_group_id
                                    and n.contact_country_id   = cc.contact_country_id
                                    and n.contact_region       = cc.contact_region);

                update cc
                set contact_count = n.contact_count,
                    run_id        = @run_id,
                    updated_at    = sysdatetime()
                from Layercake.etl_daily_count_cell_contacts cc
                inner join #dc_new n
                    on  n.[date]               = cc.[date]
                    and n.region               = cc.region
                    and n.country_id           = cc.country_id
                    and n.gender_id            = cc.gender_id
                    and n.grade                = cc.grade
                    and n.membership_status_id = cc.membership_status_id
                    and n.payment_method_id    = cc.payment_method_id
                    and n.payer_type_id        = cc.payer_type_id
                    and n.concession_type_id   = cc.concession_type_id
                    and n.local_group_id       = cc.local_group_id
                    and n.contact_country_id   = cc.contact_country_id
                    and n.contact_region       = cc.contact_region
                where cc.contact_count <> n.contact_count;

                insert into Layercake.etl_daily_count_cell_contacts
                ([date], region, country_id, gender_id, grade, membership_status_id,
                 payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
                 contact_count, run_id, updated_at)
                select n.[date], n.region, n.country_id, n.gender_id, n.grade, n.membership_status_id,
                       n.payment_method_id, n.payer_type_id, n.concession_type_id,
                       n.local_group_id, n.contact_country_id, n.contact_region,
                       n.contact_count, @run_id, sysdatetime()
                from #dc_new n
                where not exists (select 1 from Layercake.etl_daily_count_cell_contacts cc
                                  where cc.[date]               = n.[date]
                                    and cc.region               = n.region
                                    and cc.country_id           = n.country_id
                                    and cc.gender_id            = n.gender_id
                                    and cc.grade                = n.grade
                                    and cc.membership_status_id = n.membership_status_id
                                    and cc.payment_method_id    = n.payment_method_id
                                    and cc.payer_type_id        = n.payer_type_id
                                    and cc.concession_type_id   = n.concession_type_id
                                    and cc.local_group_id       = n.local_group_id
                                    and cc.contact_country_id   = n.contact_country_id
                                    and cc.contact_region       = n.contact_region);

                -- ---- main: differences only -----------------------------
                delete t
                from Layercake.silv_daily_count t
                inner join #dc_chunk c
                    on  c.[date] = t.[date]
                where not exists (select 1 from #dc_new_main n
                                  where n.[date] = t.[date]
                                    and n.region = t.region
                                    and n.grade  = t.grade);
                set @del = @del + @@rowcount;

                update t
                set campaign_year           = n.campaign_year,
                    campaign_quarter        = n.campaign_quarter,
                    active_count            = n.active_count,
                    paid_count              = n.paid_count,
                    paid_count_event        = n.paid_count_event,
                    event_join_count        = n.event_join_count,
                    event_renewal_count     = n.event_renewal_count,
                    event_readmission_count = n.event_readmission_count,
                    event_lapse_count       = n.event_lapse_count
                from Layercake.silv_daily_count t
                inner join #dc_new_main n
                    on  n.[date] = t.[date]
                    and n.region = t.region
                    and n.grade  = t.grade
                where t.campaign_year           <> n.campaign_year
                   or t.campaign_quarter        <> n.campaign_quarter
                   or t.active_count            <> n.active_count
                   or t.paid_count              <> n.paid_count
                   or t.paid_count_event        <> n.paid_count_event
                   or t.event_join_count        <> n.event_join_count
                   or t.event_renewal_count     <> n.event_renewal_count
                   or t.event_readmission_count <> n.event_readmission_count
                   or t.event_lapse_count       <> n.event_lapse_count;
                set @upd = @upd + @@rowcount;

                insert into Layercake.silv_daily_count
                ([date], campaign_year, campaign_quarter, region, grade,
                 active_count, paid_count, paid_count_event,
                 event_join_count, event_renewal_count, event_readmission_count, event_lapse_count)
                select n.[date], n.campaign_year, n.campaign_quarter, n.region, n.grade,
                       n.active_count, n.paid_count, n.paid_count_event,
                       n.event_join_count, n.event_renewal_count, n.event_readmission_count, n.event_lapse_count
                from #dc_new_main n
                where not exists (select 1 from Layercake.silv_daily_count t
                                  where t.[date] = n.[date]
                                    and t.region = n.region
                                    and t.grade  = n.grade);
                set @ins = @ins + @@rowcount;

                -- ---- mark the batch loaded (ATOMIC with its data) -------
                -- today included: its first load is a first load, and every
                -- later reload of today records its changes (RULE-114)
                insert into Layercake.etl_daily_count_loaded ([date], run_id, batch_from, batch_to)
                select c.[date], @run_id, @win_from, @win_to
                from #dc_chunk c
                where not exists (select 1 from Layercake.etl_daily_count_loaded l
                                  where l.[date] = c.[date]);
                set @marked = @@rowcount;
            end
            else
            begin
                -- ---- mode D: add new minus old to the touched cells ------
                -- A cell exists while a contact sits in it (Q-059): one whose
                -- contact count falls to 0 is removed, whatever its measures.
                truncate table #dc_apply;

                insert into #dc_apply
                ([date], campaign_year, campaign_quarter, region, country_id, gender_id, grade, membership_status_id,
                 payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
                 detail_found, count_found, contact_count,
                 old_active, old_paid, old_paid_event, old_join, old_renewal, old_readmission, old_lapse,
                 new_active, new_paid, new_paid_event, new_join, new_renewal, new_readmission, new_lapse)
                select n.[date], n.campaign_year, n.campaign_quarter, n.region, n.country_id, n.gender_id, n.grade,
                       n.membership_status_id, n.payment_method_id, n.payer_type_id, n.concession_type_id,
                       n.local_group_id, n.contact_country_id, n.contact_region,
                       iif(d.[date] is null, 0, 1),
                       iif(cc.[date] is null, 0, 1),
                       k.cnt,
                       isnull(d.active_count, 0), isnull(d.paid_count, 0), isnull(d.paid_count_event, 0),
                       isnull(d.event_join_count, 0), isnull(d.event_renewal_count, 0),
                       isnull(d.event_readmission_count, 0), isnull(d.event_lapse_count, 0),
                       iif(k.cnt > 0, isnull(d.active_count, 0)            + n.active_count, 0),
                       iif(k.cnt > 0, isnull(d.paid_count, 0)              + n.paid_count, 0),
                       iif(k.cnt > 0, isnull(d.paid_count_event, 0)        + n.paid_count_event, 0),
                       iif(k.cnt > 0, isnull(d.event_join_count, 0)        + n.event_join_count, 0),
                       iif(k.cnt > 0, isnull(d.event_renewal_count, 0)     + n.event_renewal_count, 0),
                       iif(k.cnt > 0, isnull(d.event_readmission_count, 0) + n.event_readmission_count, 0),
                       iif(k.cnt > 0, isnull(d.event_lapse_count, 0)       + n.event_lapse_count, 0)
                from #dc_new n
                left join Layercake.silv_daily_count_detail d
                    on  d.[date]               = n.[date]
                    and d.region               = n.region
                    and d.country_id           = n.country_id
                    and d.gender_id            = n.gender_id
                    and d.grade                = n.grade
                    and d.membership_status_id = n.membership_status_id
                    and d.payment_method_id    = n.payment_method_id
                    and d.payer_type_id        = n.payer_type_id
                    and d.concession_type_id   = n.concession_type_id
                    and d.local_group_id       = n.local_group_id
                    and d.contact_country_id   = n.contact_country_id
                    and d.contact_region       = n.contact_region
                left join Layercake.etl_daily_count_cell_contacts cc
                    on  cc.[date]               = n.[date]
                    and cc.region               = n.region
                    and cc.country_id           = n.country_id
                    and cc.gender_id            = n.gender_id
                    and cc.grade                = n.grade
                    and cc.membership_status_id = n.membership_status_id
                    and cc.payment_method_id    = n.payment_method_id
                    and cc.payer_type_id        = n.payer_type_id
                    and cc.concession_type_id   = n.concession_type_id
                    and cc.local_group_id       = n.local_group_id
                    and cc.contact_country_id   = n.contact_country_id
                    and cc.contact_region       = n.contact_region
                cross apply (select isnull(cc.contact_count, 0) + n.contact_count as cnt) k;

                -- ---- adjustment history (REQ-019): stored new minus old --
                insert into Layercake.silv_daily_count_adjustment
                (run_id, load_id, written_at, [date], region, country_id, gender_id, grade, membership_status_id,
                 payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
                 active_count_change, paid_count_change, paid_count_event_change, event_join_count_change,
                 event_renewal_count_change, event_readmission_count_change, event_lapse_count_change)
                select @run_id, @log_id, sysdatetime(),
                       a.[date], a.region, a.country_id, a.gender_id, a.grade, a.membership_status_id,
                       a.payment_method_id, a.payer_type_id, a.concession_type_id,
                       a.local_group_id, a.contact_country_id, a.contact_region,
                       a.new_active - a.old_active, a.new_paid - a.old_paid, a.new_paid_event - a.old_paid_event,
                       a.new_join - a.old_join, a.new_renewal - a.old_renewal,
                       a.new_readmission - a.old_readmission, a.new_lapse - a.old_lapse
                from #dc_apply a
                where exists (select 1 from Layercake.etl_daily_count_loaded l where l.[date] = a.[date])
                  and (a.new_active <> a.old_active or a.new_paid <> a.old_paid or a.new_paid_event <> a.old_paid_event
                       or a.new_join <> a.old_join or a.new_renewal <> a.old_renewal
                       or a.new_readmission <> a.old_readmission or a.new_lapse <> a.old_lapse);
                set @adj = @adj + @@rowcount;

                -- ---- detail ---------------------------------------------
                delete d
                from Layercake.silv_daily_count_detail d
                inner join #dc_apply a
                    on  a.[date]               = d.[date]
                    and a.region               = d.region
                    and a.country_id           = d.country_id
                    and a.gender_id            = d.gender_id
                    and a.grade                = d.grade
                    and a.membership_status_id = d.membership_status_id
                    and a.payment_method_id    = d.payment_method_id
                    and a.payer_type_id        = d.payer_type_id
                    and a.concession_type_id   = d.concession_type_id
                    and a.local_group_id       = d.local_group_id
                    and a.contact_country_id   = d.contact_country_id
                    and a.contact_region       = d.contact_region
                where a.contact_count <= 0;
                set @del = @del + @@rowcount;

                update d
                set campaign_year           = a.campaign_year,
                    campaign_quarter        = a.campaign_quarter,
                    active_count            = a.new_active,
                    paid_count              = a.new_paid,
                    paid_count_event        = a.new_paid_event,
                    event_join_count        = a.new_join,
                    event_renewal_count     = a.new_renewal,
                    event_readmission_count = a.new_readmission,
                    event_lapse_count       = a.new_lapse
                from Layercake.silv_daily_count_detail d
                inner join #dc_apply a
                    on  a.[date]               = d.[date]
                    and a.region               = d.region
                    and a.country_id           = d.country_id
                    and a.gender_id            = d.gender_id
                    and a.grade                = d.grade
                    and a.membership_status_id = d.membership_status_id
                    and a.payment_method_id    = d.payment_method_id
                    and a.payer_type_id        = d.payer_type_id
                    and a.concession_type_id   = d.concession_type_id
                    and a.local_group_id       = d.local_group_id
                    and a.contact_country_id   = d.contact_country_id
                    and a.contact_region       = d.contact_region
                where a.contact_count > 0
                  and (d.campaign_year           <> a.campaign_year
                       or d.campaign_quarter        <> a.campaign_quarter
                       or d.active_count            <> a.new_active
                       or d.paid_count              <> a.new_paid
                       or d.paid_count_event        <> a.new_paid_event
                       or d.event_join_count        <> a.new_join
                       or d.event_renewal_count     <> a.new_renewal
                       or d.event_readmission_count <> a.new_readmission
                       or d.event_lapse_count       <> a.new_lapse);
                set @upd = @upd + @@rowcount;

                insert into Layercake.silv_daily_count_detail
                ([date], campaign_year, campaign_quarter, region, country_id, gender_id, grade, membership_status_id,
                 payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
                 active_count, paid_count, paid_count_event,
                 event_join_count, event_renewal_count, event_readmission_count, event_lapse_count)
                select a.[date], a.campaign_year, a.campaign_quarter, a.region, a.country_id, a.gender_id, a.grade,
                       a.membership_status_id, a.payment_method_id, a.payer_type_id, a.concession_type_id,
                       a.local_group_id, a.contact_country_id, a.contact_region,
                       a.new_active, a.new_paid, a.new_paid_event,
                       a.new_join, a.new_renewal, a.new_readmission, a.new_lapse
                from #dc_apply a
                where a.contact_count > 0
                  and a.detail_found = 0;
                set @ins = @ins + @@rowcount;

                -- ---- cell contact counts --------------------------------
                delete cc
                from Layercake.etl_daily_count_cell_contacts cc
                inner join #dc_apply a
                    on  a.[date]               = cc.[date]
                    and a.region               = cc.region
                    and a.country_id           = cc.country_id
                    and a.gender_id            = cc.gender_id
                    and a.grade                = cc.grade
                    and a.membership_status_id = cc.membership_status_id
                    and a.payment_method_id    = cc.payment_method_id
                    and a.payer_type_id        = cc.payer_type_id
                    and a.concession_type_id   = cc.concession_type_id
                    and a.local_group_id       = cc.local_group_id
                    and a.contact_country_id   = cc.contact_country_id
                    and a.contact_region       = cc.contact_region
                where a.contact_count <= 0;

                update cc
                set contact_count = a.contact_count,
                    run_id        = @run_id,
                    updated_at    = sysdatetime()
                from Layercake.etl_daily_count_cell_contacts cc
                inner join #dc_apply a
                    on  a.[date]               = cc.[date]
                    and a.region               = cc.region
                    and a.country_id           = cc.country_id
                    and a.gender_id            = cc.gender_id
                    and a.grade                = cc.grade
                    and a.membership_status_id = cc.membership_status_id
                    and a.payment_method_id    = cc.payment_method_id
                    and a.payer_type_id        = cc.payer_type_id
                    and a.concession_type_id   = cc.concession_type_id
                    and a.local_group_id       = cc.local_group_id
                    and a.contact_country_id   = cc.contact_country_id
                    and a.contact_region       = cc.contact_region
                where a.contact_count > 0
                  and cc.contact_count <> a.contact_count;

                insert into Layercake.etl_daily_count_cell_contacts
                ([date], region, country_id, gender_id, grade, membership_status_id,
                 payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id, contact_region,
                 contact_count, run_id, updated_at)
                select a.[date], a.region, a.country_id, a.gender_id, a.grade, a.membership_status_id,
                       a.payment_method_id, a.payer_type_id, a.concession_type_id,
                       a.local_group_id, a.contact_country_id, a.contact_region,
                       a.contact_count, @run_id, sysdatetime()
                from #dc_apply a
                where a.contact_count > 0
                  and a.count_found = 0;

                -- ---- main: the touched rows, as the sum of their detail ---
                truncate table #dc_touch;

                insert into #dc_touch ([date], region, grade)
                select distinct a.[date], a.region, a.grade
                from #dc_apply a;

                truncate table #dc_new_main;

                insert into #dc_new_main
                ([date], campaign_year, campaign_quarter, region, grade,
                 active_count, paid_count, paid_count_event,
                 event_join_count, event_renewal_count, event_readmission_count, event_lapse_count)
                select
                    d.[date], d.campaign_year, d.campaign_quarter, d.region, d.grade,
                    sum(d.active_count), sum(d.paid_count), sum(d.paid_count_event),
                    sum(d.event_join_count), sum(d.event_renewal_count),
                    sum(d.event_readmission_count), sum(d.event_lapse_count)
                from Layercake.silv_daily_count_detail d
                inner join #dc_touch x
                    on  x.[date] = d.[date]
                    and x.region = d.region
                    and x.grade  = d.grade
                group by d.[date], d.campaign_year, d.campaign_quarter, d.region, d.grade;

                delete t
                from Layercake.silv_daily_count t
                inner join #dc_touch x
                    on  x.[date] = t.[date]
                    and x.region = t.region
                    and x.grade  = t.grade
                where not exists (select 1 from #dc_new_main n
                                  where n.[date] = t.[date]
                                    and n.region = t.region
                                    and n.grade  = t.grade);
                set @del = @del + @@rowcount;

                update t
                set campaign_year           = n.campaign_year,
                    campaign_quarter        = n.campaign_quarter,
                    active_count            = n.active_count,
                    paid_count              = n.paid_count,
                    paid_count_event        = n.paid_count_event,
                    event_join_count        = n.event_join_count,
                    event_renewal_count     = n.event_renewal_count,
                    event_readmission_count = n.event_readmission_count,
                    event_lapse_count       = n.event_lapse_count
                from Layercake.silv_daily_count t
                inner join #dc_new_main n
                    on  n.[date] = t.[date]
                    and n.region = t.region
                    and n.grade  = t.grade
                where t.campaign_year           <> n.campaign_year
                   or t.campaign_quarter        <> n.campaign_quarter
                   or t.active_count            <> n.active_count
                   or t.paid_count              <> n.paid_count
                   or t.paid_count_event        <> n.paid_count_event
                   or t.event_join_count        <> n.event_join_count
                   or t.event_renewal_count     <> n.event_renewal_count
                   or t.event_readmission_count <> n.event_readmission_count
                   or t.event_lapse_count       <> n.event_lapse_count;
                set @upd = @upd + @@rowcount;

                insert into Layercake.silv_daily_count
                ([date], campaign_year, campaign_quarter, region, grade,
                 active_count, paid_count, paid_count_event,
                 event_join_count, event_renewal_count, event_readmission_count, event_lapse_count)
                select n.[date], n.campaign_year, n.campaign_quarter, n.region, n.grade,
                       n.active_count, n.paid_count, n.paid_count_event,
                       n.event_join_count, n.event_renewal_count, n.event_readmission_count, n.event_lapse_count
                from #dc_new_main n
                where not exists (select 1 from Layercake.silv_daily_count t
                                  where t.[date] = n.[date]
                                    and t.region = n.region
                                    and t.grade  = n.grade);
                set @ins = @ins + @@rowcount;

                set @marked = 0;
            end

            commit;    -- one transaction per batch: small, quick, resumable
            set @withdrawn = 1;

            set @note = concat(N'batch ', @mode, N' ', convert(nvarchar(10), @win_from, 23),
                               N' -> ',   convert(nvarchar(10), @win_to,  23),
                               N' (', @rc, N' detail cells derived, ', @marked, N' date(s) newly marked loaded)');
            exec Layercake.usp_etl_log_progress @log_id, @note, @rc, @substep_ts output;

            -- done with these dates
            delete t
            from #dc_todo t
            where exists (select 1 from #dc_chunk c where c.[date] = t.[date]);
        end

        /* ---- g. advance the basis and the snapshot ---------------------
           Only now, with every batch committed: a run that died mid-walk
           leaves the basis as it was (restatement markers included) and
           the snapshot out of step. The snapshot rows of the contacts this
           run applied, and of any that were out of step, are rewritten from
           the inputs the run used, so every contact's basis row and
           snapshot describe the same inputs. The pending rows the
           correction covered are stamped applied in the same transaction.
           ------------------------------------------------------------- */
        create table #rewrite (contact_no nvarchar(200) collate database_default not null primary key clustered);

        insert into #rewrite (contact_no)
        select k.contact_no from #chg k
        union
        select o.contact_no from #snap_out o;

        begin tran;

        delete b
        from Layercake.etl_daily_count_input_basis b
        where b.input_name = 'contact'
          and not exists (select 1 from #in_cur c where c.contact_no = b.input_key);

        update b
        set input_fingerprint      = c.input_fingerprint,
            earliest_affected_date = c.earliest_affected_date,
            run_id                 = @run_id,
            updated_at             = sysdatetime()
        from Layercake.etl_daily_count_input_basis b
        inner join #in_cur c
            on  b.input_name = 'contact'
            and b.input_key  = c.contact_no
        where b.input_fingerprint      <> c.input_fingerprint
           or b.earliest_affected_date <> c.earliest_affected_date;

        insert into Layercake.etl_daily_count_input_basis
        (input_name, input_key, input_fingerprint, earliest_affected_date, run_id, updated_at)
        select 'contact', c.contact_no, c.input_fingerprint, c.earliest_affected_date, @run_id, sysdatetime()
        from #in_cur c
        where not exists (select 1 from Layercake.etl_daily_count_input_basis b
                          where b.input_name = 'contact'
                            and b.input_key  = c.contact_no);

        -- reference rows that have gone, and both restatement markers: every
        -- loaded date is now at the segment grain (ADR-013) and at the local
        -- group values (RULE-179)
        delete b
        from Layercake.etl_daily_count_input_basis b
        where b.input_name <> 'contact'
          and not exists (select 1 from #ref_cur r where r.input_name = b.input_name);

        update b
        set input_fingerprint = r.fp_end,
            run_id            = @run_id,
            updated_at        = sysdatetime()
        from Layercake.etl_daily_count_input_basis b
        inner join #ref_cur r
            on  r.input_name = b.input_name
        where b.input_fingerprint <> r.fp_end;

        insert into Layercake.etl_daily_count_input_basis
        (input_name, input_key, input_fingerprint, earliest_affected_date, run_id, updated_at)
        select r.input_name, N'', r.fp_end, @spine_from, @run_id, sysdatetime()
        from #ref_cur r
        where not exists (select 1 from Layercake.etl_daily_count_input_basis b
                          where b.input_name = r.input_name);

        delete a
        from Layercake.etl_daily_count_applied_state_range a
        inner join #rewrite w on w.contact_no = a.contact_no;

        delete a
        from Layercake.etl_daily_count_applied_payment a
        inner join #rewrite w on w.contact_no = a.contact_no;

        delete a
        from Layercake.etl_daily_count_applied_event a
        inner join #rewrite w on w.contact_no = a.contact_no;

        delete a
        from Layercake.etl_daily_count_applied_attribute a
        inner join #rewrite w on w.contact_no = a.contact_no;

        delete h
        from Layercake.etl_daily_count_applied_contact h
        inner join #rewrite w on w.contact_no = h.contact_no;

        insert into Layercake.etl_daily_count_applied_contact
        (contact_no, profile_found, country_id, gender_id, retirement_date, local_group_id, contact_country_id,
         run_id, updated_at)
        select c.contact_no, iif(pr.contact_no is null, 0, 1), pr.country_id, pr.gender_id, pr.retirement_date,
               pr.local_group_id, pr.contact_country_id, @run_id, sysdatetime()
        from #in_cur c
        inner join #rewrite w
            on  w.contact_no = c.contact_no
        left join #prof pr
            on  pr.side       = 'C'
            and pr.contact_no = c.contact_no;

        insert into Layercake.etl_daily_count_applied_state_range
        (contact_no, valid_from, valid_to, grade, region, contact_region)
        select r.contact_no, r.valid_from, r.valid_to, r.grade, r.region, r.contact_region
        from #rng r
        inner join #rewrite w
            on  w.contact_no = r.contact_no
        where r.side = 'C';

        insert into Layercake.etl_daily_count_applied_payment (contact_no, campaign_year, renewal_date_adj)
        select p.contact_no, p.campaign_year, p.renewal_date_adj
        from #pay p
        inner join #rewrite w
            on  w.contact_no = p.contact_no
        where p.side = 'C';

        insert into Layercake.etl_daily_count_applied_event (contact_no, campaign_year, event_type, event_date)
        select e.contact_no, e.campaign_year, e.event_type, e.event_date
        from #evt e
        inner join #rewrite w
            on  w.contact_no = e.contact_no
        where e.side = 'C';

        insert into Layercake.etl_daily_count_applied_attribute
        (contact_no, campaign_year, payment_method_id, payer_type_id, concession_type_id)
        select a.contact_no, a.campaign_year, a.payment_method_id, a.payer_type_id, a.concession_type_id
        from #attr a
        inner join #rewrite w
            on  w.contact_no = a.contact_no
        where a.side = 'C';

        update Layercake.etl_daily_count_pending_rebuild
        set applied_at = sysdatetime()
        where applied_at is null
          and affected_from >= @start;
        set @pend = @@rowcount;

        commit;

        set @note = concat(N'input basis and snapshot advanced; ', @adj, N' adjustment row(s) written',
                           iif(@restate = 1, N', restated at the segment grain', N''),
                           iif(@lg_restate = 1, N', restated by local group', N''),
                           iif(@pend > 0, concat(N', ', @pend, N' pending row(s) stamped applied'), N''));
        exec Layercake.usp_etl_log_progress @log_id, @note, @adj, @substep_ts output;

        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, @del;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, @del, @err;
        throw;
    end catch
end
GO
-- Layercake.usp_load_fact_daily_member_count_detail (src/sql/Layercake/Procedures/Layercake.usp_load_fact_daily_member_count_detail.sql) (changed)
/*====================================================================
    Layercake.usp_load_fact_daily_member_count_detail
    Gold layer - loads one table
====================================================================*/

/*====================================================================
    11. Layercake.fact_daily_member_count_detail
    ------------------------------------------------------------------
    BATCHED star sync from silv_daily_count_detail.

    Key mapping (all resolved through the dims, no strings on the fact):
      grade 'enrolment' -> membership_grade 'Candidate'
      grade 'election'  -> membership_grade 'Qualified'
                           (status carried from silver: Practising /
                            Retired)
      grade 'lapse'     -> grade 'N/A' (0) + status 'N/A' (0) - lapsing
                           is purely an EVENT (see the Lapse rows of
                           fact_membership_events); the rows stay only
                           so their PAID counts keep reconciling (active
                           is 0 anyway)
      anything else     -> grade 0 / status 0 (defensive)
      payment_method_id, payer_type_id, concession_type_id (MOD-028,
                        RULE-164) -> copied from silver: the
                           dim_payment_method / dim_payer_type /
                           dim_concession_type keys equal the silver ids
      local_group_id, contact_country_id (MOD-031, RULE-176) -> copied
                           from silver: the dim_local_group key and the
                           dim_country key of the own country
      country_id (MOD-031, gold country by local group, ADR-015) -> the
                           silv_ref_local_group.dim_country_id of a
                           reportable local group, so region rolls up
                           from dim_country to the group's region; else
                           the silver country_id (the own country's row)

    The silver grain includes the range regions; the star grain does
    not, so the SUM/GROUP BY here also collapses region and
    contact_region - region reporting rolls up from dim_country, through
    country_id (by local group) and contact_country_id (own country).

    MEASURES: every one is a straight SUM of its silver column, renamed
    to the star's PascalCase. The two paid readings travel together -
    PaidMembers (payment-driven) and PaidMembersEvent (event-driven:
    Join + Renewal + Readmission, resetting each 1 October, with lapsing
    NOT deducting) - plus JoinEvents / RenewalEvents / ReadmissionEvents
    carrying the daily flows the second is built from and LapseEvents
    reported alongside them. The rules behind all six live in
    usp_load_silv_daily_count; nothing is re-derived here.

    BATCHING: the silver date span is walked in @DetailBatchDays
    windows. Per window: stage the silver aggregate, then sync the fact
    CELL BY CELL (MOD-027, RULE-150) on the ten-column star grain
    (MOD-031): a fact cell with no silver cell is deleted, a cell whose
    measures differ is updated in place and keeps its id, a new cell is
    inserted, an unchanged cell is not touched.
    COMMIT per window. rows_inserted / rows_updated / rows_deleted count
    exactly those cells, so a rerun on unchanged silver logs 0 / 0 / 0.
    Small transactions, small scans, steady progress in etl_progress_log
    - built for Azure SQL.
    First run after deploy: the fact is empty, every window backfills -
    one-off, expected.
====================================================================*/
create or alter procedure Layercake.usp_load_fact_daily_member_count_detail
    @run_id          uniqueidentifier = null,
    @DetailBatchDays int = 31              -- date-window size for the batched load
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();
    if @DetailBatchDays < 1 set @DetailBatchDays = 1;

    declare @log_id     bigint,
            @ins        int,
            @upd        int,
            @del        int,
            @rc         int,
            @win_cells  int,
            @note       nvarchar(128),
            @substep_ts datetime2(3),
            @src_count  bigint,
            @tgt_count  bigint,
            @err        nvarchar(4000);

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'gold', 'fact_daily_member_count_detail', @log_id output;
        set @substep_ts = sysdatetime();

        declare @grade_candidate_id int = (select id from Layercake.dim_membership_grade where grade_name = 'Candidate'),
                @grade_qualified_id int = (select id from Layercake.dim_membership_grade where grade_name = 'Qualified');

        if @grade_candidate_id is null or @grade_qualified_id is null
            raiserror('dim_membership_grade is missing the Candidate/Qualified members - run usp_load_dim_membership_grade (and deploy the baseline DDL) before this module.', 16, 1);

        declare @span_from date = (select min([date]) from Layercake.silv_daily_count_detail),
                @span_to   date = (select max([date]) from Layercake.silv_daily_count_detail),
                @win_from  date,
                @win_to    date;

        select @ins = 0, @upd = 0, @del = 0, @src_count = 0;

        -- gold rows for dates silver no longer covers at all (span moved, or
        -- silver emptied) - outside the window walk, so trimmed up front
        begin tran;
        delete tgt
        from Layercake.fact_daily_member_count_detail tgt
        join Layercake.dim_date d on d.id = tgt.date_id
        where @span_from is null
           or d.[date] < @span_from
           or d.[date] > @span_to;
        set @rc = @@rowcount;
        set @del = @del + @rc;
        commit;
        exec Layercake.usp_etl_log_progress @log_id, N'trim rows outside the silver date span', @rc, @substep_ts output;

        -- window work table, created once, truncated per window
        create table #det_stage
        (
            date_id              int not null,
            country_id           int not null,
            gender_id            int not null,
            membership_grade_id  int not null,
            membership_status_id int not null,
            payment_method_id    int not null,
            payer_type_id        int not null,
            concession_type_id   int not null,
            local_group_id       int not null,
            contact_country_id   int not null,
            ActiveMembers        int not null,
            PaidMembers          int not null,
            PaidMembersEvent     int not null,
            JoinEvents           int not null,
            RenewalEvents        int not null,
            ReadmissionEvents    int not null,
            LapseEvents          int not null,
            primary key clustered (date_id, country_id, gender_id, membership_grade_id, membership_status_id,
                                   payment_method_id, payer_type_id, concession_type_id,
                                   local_group_id, contact_country_id)
        );

        set @win_from = @span_from;
        while @win_from is not null and @win_from <= @span_to
        begin
            set @win_to = dateadd(day, @DetailBatchDays - 1, @win_from);
            if @win_to > @span_to set @win_to = @span_to;

            truncate table #det_stage;
            set @win_cells = @ins + @upd + @del;

            begin tran;

            -- stage this window's silver aggregate at the star grain
            insert into #det_stage
            (date_id, country_id, gender_id, membership_grade_id, membership_status_id,
             payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id,
             ActiveMembers, PaidMembers, PaidMembersEvent,
             JoinEvents, RenewalEvents, ReadmissionEvents, LapseEvents)
            select
                dd.id,
                isnull(lg.dim_country_id, dc.country_id),
                dc.gender_id,
                case dc.grade
                    when 'enrolment' then @grade_candidate_id
                    when 'election'  then @grade_qualified_id
                    else 0                                   -- lapse (and any unknown state) -> N/A grade
                end,
                case when dc.grade = 'election' then dc.membership_status_id
                     else 0                                  -- lapse is event-only: N/A status
                end,
                dc.payment_method_id,
                dc.payer_type_id,
                dc.concession_type_id,
                dc.local_group_id,
                dc.contact_country_id,
                sum(dc.active_count),
                sum(dc.paid_count),
                sum(dc.paid_count_event),
                sum(dc.event_join_count),
                sum(dc.event_renewal_count),
                sum(dc.event_readmission_count),
                sum(dc.event_lapse_count)
            from Layercake.silv_daily_count_detail dc
            join Layercake.dim_date dd on dd.[date] = dc.[date]
            -- gold country by local group (ADR-015): a reportable group's
            -- dim_country row carries the group's regions
            left join Layercake.silv_ref_local_group lg
                on  lg.id            = dc.local_group_id
                and lg.is_reportable = 1
            where dc.[date] between @win_from and @win_to
            group by
                dd.id,
                isnull(lg.dim_country_id, dc.country_id),
                dc.gender_id,
                case dc.grade
                    when 'enrolment' then @grade_candidate_id
                    when 'election'  then @grade_qualified_id
                    else 0
                end,
                case when dc.grade = 'election' then dc.membership_status_id
                     else 0
                end,
                dc.payment_method_id,
                dc.payer_type_id,
                dc.concession_type_id,
                dc.local_group_id,
                dc.contact_country_id;
            set @rc = @@rowcount;
            set @src_count = @src_count + @rc;

            -- fact cells in this window that silver no longer holds
            delete tgt
            from Layercake.fact_daily_member_count_detail tgt
            join Layercake.dim_date d on d.id = tgt.date_id
            where d.[date] between @win_from and @win_to
              and not exists (select 1
                              from #det_stage s
                              where s.date_id              = tgt.date_id
                                and s.country_id           = tgt.country_id
                                and s.gender_id            = tgt.gender_id
                                and s.membership_grade_id  = tgt.membership_grade_id
                                and s.membership_status_id = tgt.membership_status_id
                                and s.payment_method_id    = tgt.payment_method_id
                                and s.payer_type_id        = tgt.payer_type_id
                                and s.concession_type_id   = tgt.concession_type_id
                                and s.local_group_id       = tgt.local_group_id
                                and s.contact_country_id   = tgt.contact_country_id);
            set @del = @del + @@rowcount;

            -- changed cells: updated in place, so they keep their id; the
            -- measures are int not null, so <> sees every change
            update tgt
            set tgt.ActiveMembers     = s.ActiveMembers,
                tgt.PaidMembers       = s.PaidMembers,
                tgt.PaidMembersEvent  = s.PaidMembersEvent,
                tgt.JoinEvents        = s.JoinEvents,
                tgt.RenewalEvents     = s.RenewalEvents,
                tgt.ReadmissionEvents = s.ReadmissionEvents,
                tgt.LapseEvents       = s.LapseEvents
            from Layercake.fact_daily_member_count_detail tgt
            join #det_stage s
              on  s.date_id              = tgt.date_id
              and s.country_id           = tgt.country_id
              and s.gender_id            = tgt.gender_id
              and s.membership_grade_id  = tgt.membership_grade_id
              and s.membership_status_id = tgt.membership_status_id
              and s.payment_method_id    = tgt.payment_method_id
              and s.payer_type_id        = tgt.payer_type_id
              and s.concession_type_id   = tgt.concession_type_id
              and s.local_group_id       = tgt.local_group_id
              and s.contact_country_id   = tgt.contact_country_id
            where tgt.ActiveMembers     <> s.ActiveMembers
               or tgt.PaidMembers       <> s.PaidMembers
               or tgt.PaidMembersEvent  <> s.PaidMembersEvent
               or tgt.JoinEvents        <> s.JoinEvents
               or tgt.RenewalEvents     <> s.RenewalEvents
               or tgt.ReadmissionEvents <> s.ReadmissionEvents
               or tgt.LapseEvents       <> s.LapseEvents;
            set @upd = @upd + @@rowcount;

            -- new cells
            insert into Layercake.fact_daily_member_count_detail
            (date_id, country_id, gender_id, membership_grade_id, membership_status_id,
             payment_method_id, payer_type_id, concession_type_id, local_group_id, contact_country_id,
             ActiveMembers, PaidMembers, PaidMembersEvent,
             JoinEvents, RenewalEvents, ReadmissionEvents, LapseEvents)
            select s.date_id, s.country_id, s.gender_id, s.membership_grade_id, s.membership_status_id,
                   s.payment_method_id, s.payer_type_id, s.concession_type_id, s.local_group_id, s.contact_country_id,
                   s.ActiveMembers, s.PaidMembers, s.PaidMembersEvent,
                   s.JoinEvents, s.RenewalEvents, s.ReadmissionEvents, s.LapseEvents
            from #det_stage s
            where not exists (select 1
                              from Layercake.fact_daily_member_count_detail tgt
                              where tgt.date_id              = s.date_id
                                and tgt.country_id           = s.country_id
                                and tgt.gender_id            = s.gender_id
                                and tgt.membership_grade_id  = s.membership_grade_id
                                and tgt.membership_status_id = s.membership_status_id
                                and tgt.payment_method_id    = s.payment_method_id
                                and tgt.payer_type_id        = s.payer_type_id
                                and tgt.concession_type_id   = s.concession_type_id
                                and tgt.local_group_id       = s.local_group_id
                                and tgt.contact_country_id   = s.contact_country_id);
            set @ins = @ins + @@rowcount;

            commit;    -- one transaction per window: small, quick, self-healing

            set @win_cells = @ins + @upd + @del - @win_cells;
            set @note = concat(N'window ', convert(nvarchar(10), @win_from, 23),
                               N' -> ',    convert(nvarchar(10), @win_to,  23),
                               N' (', @win_cells, N' cells synced)');
            exec Layercake.usp_etl_log_progress @log_id, @note, @rc, @substep_ts output;

            set @win_from = dateadd(day, 1, @win_to);
        end

        drop table #det_stage;

        -- gold should reconcile exactly back to silver: the accumulated stage
        -- rowcount across all windows is the full silver aggregate at the
        -- star grain, and the windows partition the span
        select @tgt_count = count(*) from Layercake.fact_daily_member_count_detail;
        if @src_count <> @tgt_count
            raiserror('Row count mismatch after sync of Layercake.fact_daily_member_count_detail vs silv_daily_count_detail aggregate: %I64d vs %I64d.', 16, 1, @src_count, @tgt_count);

        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, @del;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, @del, @err;
        throw;
    end catch
end
GO
-- ===== changes end =====
EXEC Layercake.usp_record_migration @migration_id = 'MIG-0033', @module_id = 'MOD-031',
     @description = N'Member base, profile and daily counts by local group', @direction = 'up',
     @script_name = N'MIG-0033_MOD-031_member-base-profile-and-daily-counts-by.up.sql', @commit_hash = '$(CommitHash)';
COMMIT;
GO
SET NOEXEC OFF;
